/* lore/ru.lore.js — v613: descriptions for the "Описание созвездий" tab (core/lore.js), written for the site
   (own words, not copied from any book or wiki). Loaded only when the tab is opened. */
KC.addLore("ru", {
  "dnd.al.CE": "Хаотично-злой — мировоззрение тех, кто действует под влиянием жестокости, ярости или жажды разрушения. Такие персонажи не признают никаких правил и ограничений, руководствуясь лишь своими желаниями. Это образ безумного разрушителя или демона Бездны. Они самые непредсказуемые и опасные противники.",
  "dnd.al.CG": "Хаотично-добрый — мировоззрение тех, кто делает добро, руководствуясь собственной совестью, а не законами. Такие персонажи ценят свободу, недолюбливают правила и авторитеты и готовы нарушить закон ради благого дела. Это образ благородного разбойника или бунтаря против тирании. Они добры сердцем, но непредсказуемы.",
  "dnd.al.CN": "Хаотично-нейтральный — мировоззрение тех, кто ценит личную свободу превыше всего. Такие персонажи следуют своим желаниям и прихотям, не заботясь особо ни о законах, ни о морали. Они не обязательно жестоки, но и не стремятся помогать другим без причины. Это образ свободолюбивого бродяги или непредсказуемого авантюриста.",
  "dnd.al.LE": "Законно-злой — мировоззрение тех, кто преследует корыстные или жестокие цели в рамках строгого порядка, иерархии или кодекса. Такие персонажи используют закон как инструмент власти и держат своё слово, когда это выгодно. Это образ тирана, коварного дипломата или дьявола, заключающего сделки. Они опасны своей расчётливостью.",
  "dnd.al.LG": "Законно-добрый — мировоззрение, сочетающее стремление к добру с уважением к закону, порядку и данному слову. Такие персонажи поступают правильно, потому что верят в справедливость и честь, и ожидают того же от других. Это классический образ благородного рыцаря, честного судьи или преданного защитника. Им может быть сложно, когда закон противоречит морали.",
  "dnd.al.LN": "Законно-нейтральный — мировоззрение тех, кто следует закону, традиции или личному кодексу превыше всего, независимо от того, добр он или зол. Такие персонажи ценят порядок, дисциплину и предсказуемость. Это образ бесстрастного судьи, верного солдата или монаха, живущего по строгим правилам. Для них правило важнее чувств.",
  "dnd.al.NE": "Нейтрально-злой — мировоззрение тех, кто ставит собственную выгоду выше всего, не заботясь ни о порядке, ни о хаосе. Такие персонажи готовы на что угодно ради своих целей, если им это сойдёт с рук. Они не обязательно стремятся к разрушению, но и не испытывают угрызений совести. Это образ наёмника без принципов.",
  "dnd.al.NG": "Нейтрально-добрый — мировоззрение тех, кто делает добро без особой привязки к правилам или их нарушению. Такие персонажи помогают другим, потому что это правильно, и выбирают тот путь, который принесёт больше пользы. Они могут сотрудничать с властью или действовать в обход неё. Это образ доброго целителя или бескорыстного помощника.",
  "dnd.al.NN": "Истинно нейтральный — мировоззрение тех, кто не склоняется ни к добру, ни к злу, ни к закону, ни к хаосу. Одни такие персонажи просто живут своей жизнью и избегают моральных вопросов, другие сознательно стремятся к равновесию сил в мире. Это часто образ друида, хранящего баланс природы. Они действуют по обстоятельствам.",
  "dnd.c.artificer": "Изобретатель — мастер, соединяющий магию и ремесло: его заклинания проявляются через инструменты, механизмы и зачарованные предметы. Класс появился в сеттинге Эберрон, где магия встроена в технологию, а позже вошёл в «Котёл Таши». Изобретатели создают и улучшают магические предметы, делясь ими с союзниками. Это изобретательный персонаж поддержки и решатель проблем, хорошо чувствующий себя и в бою, и в мастерской.",
  "dnd.c.barbarian": "Варвар — свирепый воин, черпающий силу в первобытной ярости. В гневе он становится крепче, бьёт сильнее и почти не замечает ран. Варвары часто происходят из диких или пограничных земель и больше доверяют инстинктам, чем правилам цивилизации. Это классический боец передней линии, который идёт в самую гущу схватки и принимает на себя удары врагов.",
  "dnd.c.bard": "Бард — мастер слова, музыки и магии, верящий, что в мире звучит творческая сила, которую можно направлять. Барды вдохновляют союзников, сбивают с толку врагов и используют заклинания очарования, исцеления и иллюзий. Они знают понемногу обо всём и легко находят общий язык с людьми. Это гибкий персонаж поддержки, одинаково полезный в переговорах, разведке и бою.",
  "dnd.c.cleric": "Жрец — служитель божества или высшей силы, наделённый божественной магией. Жрецы исцеляют раненых, защищают союзников, изгоняют нежить и обрушивают на врагов кару небес. Характер жреца во многом определяется его доменом — сферой влияния божества, будь то жизнь, буря, война или обман. Жрецы носят доспехи и способны сражаться, сочетая роль целителя и бойца.",
  "dnd.c.druid": "Друид — хранитель природы, черпающий силу из самой жизни мира, стихий и древних первобытных сил. Друиды умеют принимать облик зверей, повелевать растениями, погодой и стихиями, а также исцелять. Они часто живут вдали от городов и защищают равновесие между цивилизацией и дикой природой. Гибкий заклинатель, способный и поддерживать союзников, и сражаться в зверином облике.",
  "dnd.c.fighter": "Воин — профессионал боя, владеющий любым оружием и доспехами. Это может быть рыцарь, наёмник, гладиатор или ветеран войны — всех их объединяет отточенное мастерство и выносливость. Воины атакуют чаще других и умеют быстро приходить в себя посреди битвы. Класс прост в освоении, но благодаря подклассам позволяет создать очень разных персонажей — от тактика до боевого мага.",
  "dnd.c.monk": "Монах — мастер боевых искусств, сражающийся голыми руками и простым оружием и направляющий внутреннюю энергию тела. Монахи невероятно быстры, ловко уклоняются от атак и умеют совершать подвиги, кажущиеся сверхъестественными. Многие из них прошли обучение в монастырях с собственными традициями и философией. Это подвижный боец, который обрушивает на врага шквал ударов и стремительно меняет позицию.",
  "dnd.c.paladin": "Паладин — святой воин, чья сила рождается из принесённой клятвы. Паладины сочетают тяжёлые доспехи и мастерство оружия с божественной магией: они исцеляют, защищают союзников аурами и наносят сокрушительные священные удары. Содержание клятвы определяет их идеалы — от рыцарской чести до неумолимого возмездия. Это надёжный боец передней линии с яркой моральной позицией.",
  "dnd.c.ranger": "Следопыт — охотник и страж диких земель, сочетающий воинскую выучку с природной магией. Следопыты умеют выслеживать добычу, выживать в глуши и вести отряд по опасным маршрутам. Многие из них специализируются на борьбе с определёнными угрозами, защищая границы цивилизации. Это меткий стрелок или ловкий боец ближнего боя, полезный и в разведке, и в сражении.",
  "dnd.c.rogue": "Плут — ловкий специалист, полагающийся на хитрость, скрытность и точность. Плуты взламывают замки, обезвреживают ловушки, крадутся в тенях и наносят смертоносные удары, когда противник отвлечён. Ими могут быть воры, шпионы, разведчики или авантюристы. Плут владеет множеством навыков и особенно полезен за пределами боя, хотя и в схватке опасен.",
  "dnd.c.sorcerer": "Чародей — маг, чья сила врождённая: она течёт в его крови из-за драконьего наследия, прикосновения хаоса или иного необычного источника. Чародеи не учат заклинания по книгам, а чувствуют магию как часть себя. Их особенность — метамагия, позволяющая изменять заклинания: усиливать, ускорять или незаметно творить их. Это яркий заклинатель, который знает немного чар, но владеет ими виртуозно.",
  "dnd.c.warlock": "Колдун — заклинатель, получивший силу благодаря договору с могущественной потусторонней сущностью: исчадием, архифеей, небесным существом или чем-то ещё более странным. Колдуны знают меньше заклинаний, чем другие маги, но быстро восстанавливают магию и усиливают себя таинственными воззваниями. Отношения с покровителем — неисчерпаемый источник сюжетов: служба, долг, сомнения. Колдун хорошо сочетает атакующую магию с необычными способностями.",
  "dnd.c.wizard": "Волшебник — учёный маг, постигающий тайны магии через книги, исследования и годы упорного труда. Свои заклинания он хранит в книге заклинаний и может пополнять её новыми формулами. Волшебники обладают самым обширным арсеналом магии: от огненных шаров до телепортации и изменения реальности. Это хрупкий, но чрезвычайно гибкий персонаж, который побеждает знанием и подготовкой.",
  "dnd.r.changeling": "Чейнджлинг — оборотень по природе, способный по желанию менять внешность, голос и облик. Изначально этот народ связан с миром Эберрон, но встречается и в других сеттингах. Многие чейнджлинги используют несколько личностей для разных ситуаций, а их истинный облик — бледный, с бесцветными глазами — видят немногие. Им близки темы идентичности, маскировки и доверия. Чейнджлинги прекрасно подходят для бардов, плутов и колдунов.",
  "dnd.r.dragonborn": "Драконорождённый — народ, несущий в себе наследие драконов: чешуя, гордая осанка и способность выдыхать стихийную энергию, как у предков. Цвет чешуи и вид дыхания зависят от того, к какому роду драконов восходит персонаж — например, огонь у красных и золотых или холод у белых и серебряных. Драконорождённые высоко ставят честь, самосовершенствование и верность роду. Они хорошо смотрятся в роли воинов, паладинов и чародеев.",
  "dnd.r.drow": "Дроу — эльфы, чья история связана с Подземьем, огромным миром пещер под поверхностью. Они видят в темноте лучше большинства народов, а солнечный свет для многих из них непривычен. В классических мирах вроде Забытых Королевств общества дроу часто изображаются как жёсткие матриархаты, поклоняющиеся богине пауков Ллос, однако многие персонажи-дроу бегут от этого наследия и ищут собственный путь. В правилах 2024 года дроу — одна из эльфийских линий с врождённой магией тьмы.",
  "dnd.r.dwarf": "Дварф — крепкий и выносливый народ, издавна живущий в горных твердынях и подземных городах. Дварфы славятся как кузнецы, рудокопы и камнетёсы, умеют видеть в темноте и стойко переносят яды. Они ценят клан, традиции и данное слово, долго помнят и добро, и обиды. Это надёжные бойцы и ремесленники, которые отлично подходят для воинов, жрецов и паладинов.",
  "dnd.r.elf": "Эльф — долгоживущий народ, связанный с магией и миром фей, откуда, по преданиям, происходят его предки. Эльфы изящны, обладают острыми чувствами и не нуждаются в обычном сне — вместо него они погружаются в медитативный транс. Проживая столетия, они ценят искусство, природу и красоту и нередко смотрят на дела короткоживущих народов с лёгкой отстранённостью. Среди эльфов выделяют несколько линий, например высших и лесных эльфов.",
  "dnd.r.goliath": "Голиаф — рослый народ, ведущий родословную от великанов. Голиафы живут в суровых высокогорьях, ценят честное соревнование и личные достижения и уважают того, кто проявил себя делом. Их мощное телосложение позволяет переносить тяжести и холод, а в новых правилах они ещё и унаследовали частицу силы конкретного вида великанов — огненных, ледяных, каменных и других. Голиафы прекрасно подходят для варваров, воинов и монахов.",
  "dnd.r.halfling": "Полурослик — маленький, но удивительно стойкий народ, ценящий уют, хорошую еду и дружную компанию. Полурослики славятся почти сверхъестественным везением и умением не теряться в опасности, а их небольшой рост позволяет проскользнуть там, где другие застрянут. Многие из них мирно живут в своих общинах, но некоторых зовёт дорога и любопытство. Полурослики отлично подходят для плутов, бардов и следопытов.",
  "dnd.r.halforc": "Полуорк — потомок людей и орков, сочетающий человеческую гибкость с орочьей силой и выносливостью. Полуорки известны упорством: в критический момент они способны устоять там, где другие падают. Им нередко приходится искать своё место между двумя мирами, доказывая окружающим, чего они стоят. Классический выбор для варваров и воинов, хотя полуорк может быть кем угодно. В правилах 2024 года вместо полуорка в основной книге представлен орк.",
  "dnd.r.human": "Человек — самый распространённый народ в мирах D&D. Люди живут недолго по меркам эльфов и дварфов, но именно поэтому стремятся успеть как можно больше: строят империи, торгуют, исследуют и воюют. Их отличают приспособляемость, честолюбие и огромное разнообразие культур. Человек подходит для любого класса и любой истории — от деревенского пастуха до придворного мага.",
  "dnd.r.kenku": "Кенку — птицеподобный народ, похожий на воронов, известный умением в точности подражать любым звукам и голосам. Предания гласят, что их предки когда-то служили могущественному покровителю и утратили нечто важное, но в новых правилах кенку уже не связаны прежним проклятием. Кенку внимательны, обладают отличной памятью и умело копируют увиденное. Они хорошо подходят для плутов, следопытов и бардов.",
  "dnd.r.tabaxi": "Табакси — кошачий народ, по легендам пришедший из далёких земель. Табакси гибки, ловки и стремительны, хорошо лазают и видят в темноте, а когти служат им и оружием, и инструментом. Главная черта их характера — неутолимое любопытство: они собирают истории, диковинки и знания, но могут быстро переключаться с одного увлечения на другое. Табакси естественно смотрятся в роли плутов, следопытов, монахов и бардов.",
  "dnd.r.tiefling": "Тифлинг — человек или представитель другого народа, в чьих жилах течёт кровь нижних планов. Это видно по рогам, хвосту, необычному цвету кожи или глаз. Тифлинги обладают врождённой магией и устойчивостью, связанной с их происхождением: в правилах 2024 года выделяются инфернальное, бездновое и хтоническое наследие. Из-за внешности им часто не доверяют, поэтому многие тифлинги полагаются на собственное обаяние и решимость. Отличный выбор для колдунов, чародеев и бардов.",
  "dnd.r.yuanti": "Юань-ти — змеелюди, чьи предки ради могущества слили свою природу со змеиной в древних тёмных ритуалах. Внешне многие из них близки к людям, но выдают себя чешуёй, змеиными глазами или раздвоенным языком. Юань-ти устойчивы к ядам и чужой магии и владеют врождёнными заклинаниями. Традиционно их общества холодны и расчётливы, но персонаж-юань-ти может отвергнуть это наследие. В «Monsters of the Multiverse» они представлены как играбельный народ.",
  "dnd.s.artificer.alchemist": "Алхимик — подкласс изобретателя, мастер зелий и химических составов. Он создаёт экспериментальные эликсиры со случайными полезными эффектами и усиливает исцеляющую и атакующую магию своими познаниями. Алхимики хорошо поддерживают отряд, восстанавливая силы союзников. Подкласс подходит для любителей лабораторий и неожиданных результатов.",
  "dnd.s.artificer.armorer": "Бронник — подкласс изобретателя, превращающий доспех в магический силовой костюм. Такой изобретатель может настроить броню на роль стража, притягивающего внимание врагов, или лазутчика, действующего скрытно. Встроенное оружие доспеха и его улучшения делают бронника стойким бойцом ближнего или дальнего боя. Подкласс появился в «Котле Таши» и сочетает ремесло с образом закованного в сталь героя.",
  "dnd.s.artificer.artillerist": "Артиллерист — подкласс изобретателя, специализирующийся на разрушительной магии и магических орудиях. Он создаёт волшебную пушку, способную метать пламя, бить силовыми снарядами или защищать союзников. Его жезлы и посохи усиливают атакующие заклинания. Подкласс подходит для тех, кто хочет мощно поражать врагов на расстоянии.",
  "dnd.s.artificer.battlesmith": "Боевой кузнец — подкласс изобретателя, сочетающий роль бойца, защитника и мастера. Его главный помощник — стальной защитник, механический спутник, сражающийся рядом и прикрывающий союзников. Боевые кузнецы используют свой интеллект и в обращении с оружием, а также умеют лечить союзников. Подкласс подходит для тех, кто хочет сыграть изобретателя с верным механическим другом.",
  "dnd.s.barbarian.beast": "Путь зверя — подкласс варвара, в котором ярость пробуждает звериную природу. В гневе у варвара появляются клыки, когти или хвост, и он сражается ими как оружием. Этих варваров могла коснуться ликантропия или иной зверь, оставивший след в их крови. Подкласс из «Котла Таши» подходит для яростных диких персонажей.",
  "dnd.s.barbarian.berserker": "Путь берсерка — подкласс варвара, превращающий ярость в чистое неистовство. Берсерки бросаются в бой, не думая о защите, наносят удар за ударом и становятся невосприимчивы к страху и чарам. Их появление на поле боя пугает врагов само по себе. Это прямолинейный и мощный путь для тех, кто хочет сыграть необузданного воина.",
  "dnd.s.barbarian.stormherald": "Путь буревестника — подкласс варвара, чья ярость окружает его стихийной бурей. В гневе он излучает ауру, отражающую природу его земли: жар пустыни, мощь моря или холод тундры. Эта аура вредит врагам или защищает союзников. Подкласс из «Руководства Занатара» подходит для персонажей, связанных со стихиями.",
  "dnd.s.barbarian.wildheart": "Путь дикого сердца — подкласс варвара из «Книги игрока» 2024 года, наследник прежнего Пути тотемного воина. Его последователи считают зверей своими родичами и черпают силу их духа: медведя, орла, волка и других. В зависимости от выбранного зверя варвар становится стойким, подвижным или помогает союзникам. Подкласс подходит для персонажей, тесно связанных с дикой природой.",
  "dnd.s.bard.creation": "Коллегия созидания — подкласс барда, верящий, что мир был сотворён из первозданной песни. Такие барды вплетают в свою магию ноты творения: оживляют предметы, заставляя их танцевать, и создают вещи из ничего. Их вдохновение дарит союзникам дополнительные возможности. Подкласс из «Котла Таши» подходит для творческих и изобретательных игроков.",
  "dnd.s.bard.dance": "Коллегия танца — подкласс барда из «Книги игрока» 2024 года, превращающий движение в искусство и оружие. Такие барды сражаются без доспехов и оружия, используя грацию и ритм, словно в танце. Своим вдохновением они помогают союзникам двигаться слаженно и стремительно. Подкласс сочетает поддержку с подвижным ближним боем.",
  "dnd.s.bard.eloquence": "Коллегия красноречия — подкласс барда, мастер убеждения и ораторского искусства. Такие барды владеют словом настолько, что их доводы почти невозможно опровергнуть, а их вдохновение особенно надёжно. Они умеют как поддержать союзников, так и подорвать уверенность врагов. Подкласс подходит для дипломатов, ораторов и харизматичных лидеров.",
  "dnd.s.bard.glamour": "Коллегия очарования — подкласс барда, черпающий вдохновение в волшебстве мира фей. Такие барды овладевают магией чарующей красоты и величия: они могут пленить слушателей, внушить благоговение или страх. Их выступления воодушевляют союзников, а сама их фигура кажется окружённой сиянием. Подкласс из «Руководства Занатара» подходит для харизматичных, загадочных персонажей.",
  "dnd.s.cleric.life": "Домен жизни — подкласс жреца, посвящённый божествам жизни, здоровья и исцеления. Такие жрецы — лучшие целители среди всех классов: их лечебная магия особенно сильна, а сами они могут носить тяжёлые доспехи. Они защищают слабых, борются с болезнями и нежитью и олицетворяют силу, поддерживающую всё живое. Классический выбор для игрока, который хочет держать отряд на ногах.",
  "dnd.s.cleric.tempest": "Домен бури — подкласс жреца, служащего божествам грома, молний и моря. Такие жрецы носят тяжёлые доспехи и обрушивают на врагов силу стихии — громовые раскаты и разряды молний. Они олицетворяют ярость природы и мощь небес. Подкласс подходит для воинственных жрецов, предпочитающих нападение обороне.",
  "dnd.s.cleric.trickery": "Домен обмана — подкласс жреца, служащего божествам хитрости, озорства и перемен. Такие жрецы владеют иллюзиями, невидимостью и созданием двойников, сбивающих врагов с толку. Они бросают вызов устоявшимся порядкам и тиранам, предпочитая хитрость прямому столкновению. Подкласс подходит для изворотливых, весёлых и непредсказуемых персонажей.",
  "dnd.s.druid.dreams": "Круг снов — подкласс друида, связанный с миром фей и его волшебством. Такие друиды несут в себе частицу мечтательной, целительной силы фей: они лечат союзников, обеспечивают безопасный отдых и умеют перемещаться через лунный свет и тени. Это мягкий, поддерживающий путь для тех, кто видит в природе не только дикость, но и надежду. Подкласс представлен в «Руководстве Занатара».",
  "dnd.s.druid.land": "Круг земли — подкласс друида, связанный с определённым типом местности: пустыней, лесом, горами, болотом и другими. Такие друиды — хранители древних знаний и мистических обрядов, а их магия отражает природу родного края. Они больше полагаются на заклинания, чем на звериные облики. Классический выбор для мудрого заклинателя природы.",
  "dnd.s.druid.moon": "Круг луны — подкласс друида, посвятивший себя искусству превращения в зверей. Такие друиды принимают облики более могучих животных, чем другие, и сражаются в них на передовой. Они живут на самом краю дикой природы, повинуясь ритму луны. Подкласс подходит тем, кто хочет сыграть оборотня-защитника.",
  "dnd.s.druid.sea": "Круг моря — подкласс друида из «Книги игрока» 2024 года, связанный с силой океана и бурь. Его последователи призывают ярость моря: окружают себя ледяными брызгами и ветром, отбрасывая и раня врагов вокруг. Они ощущают приливы и течения как часть себя и со временем свободно двигаются в воде. Подкласс подходит для тех, кто хочет сыграть грозного стихийного заклинателя.",
  "dnd.s.fighter.battlemaster": "Мастер боевых искусств — подкласс воина, превращающий бой в науку. Такие воины владеют особыми приёмами: подсечками, финтами, обезоруживанием, командами союзникам. Они тщательно изучают противника и выбирают нужный манёвр в нужный момент. Подкласс подходит для тех, кто любит тактику и хочет больше вариантов в бою, чем просто атаку.",
  "dnd.s.fighter.champion": "Чемпион — подкласс воина, полагающийся на чистое физическое совершенство. Чемпионы чаще наносят критические удары, отличаются выносливостью и атлетизмом и с каждым уровнем становятся всё более грозными. Им не нужны сложные приёмы — их сила в простоте и надёжности. Отличный выбор для новичков и тех, кто хочет сыграть непобедимого бойца.",
  "dnd.s.fighter.runeknight": "Рыцарь рун — подкласс воина, овладевший древней магией великанских рун. Начертав руны на снаряжении, он получает особые силы и может на время увеличиваться до великанских размеров. Каждая руна связана с определённым видом великанов — огненных, ледяных, облачных и других. Подкласс из «Котла Таши» подходит тем, кто хочет сочетать мощь воина с оттенком магии.",
  "dnd.s.monk.astral": "Путь астрального «я» — подкласс монаха, способного проявлять свою душу в виде призрачного астрального воплощения. Сначала монах призывает астральные руки, разящие на расстоянии, а со временем — и полноценный духовный облик. Последователи этого пути верят, что тело — лишь иллюзия, а истинная сила кроется в духе. Подкласс представлен в «Котле Таши».",
  "dnd.s.monk.mercy": "Путь милосердия — подкласс монаха, последователи которого владеют искусством как исцелять, так и отнимать жизнь. Они носят маски, скрывающие их личность, и странствуют, помогая страждущим и обрывая страдания. Одним касанием такой монах может залечить раны союзника или нанести врагу вред. Подкласс появился в «Котле Таши» как Way of Mercy и в 2024 году перешёл в основную книгу.",
  "dnd.s.monk.openhand": "Путь открытой ладони — традиция монаха, совершенствующая чистое рукопашное мастерство. Его последователи учатся сбивать противников с ног, отталкивать их и лишать возможности ответить, превращая каждый удар в инструмент контроля. В высшей точке пути монах способен одним касанием нанести врагу сокрушительный вред. Это простой и надёжный выбор для тех, кто хочет почувствовать себя мастером боевых искусств.",
  "dnd.s.paladin.conquest": "Клятва покорения — подкласс паладина, чьи последователи стремятся установить порядок силой и сокрушить хаос. Такие паладины внушают врагам ужас, подавляя их волю и сковывая страхом. Их идеалы — власть, дисциплина и победа любой ценой, поэтому они часто балансируют на грани между суровым законом и тиранией. Подкласс из «Руководства Занатара» хорошо подходит для властных, грозных персонажей.",
  "dnd.s.paladin.devotion": "Клятва преданности — подкласс паладина, воплощающий классический образ рыцаря в сияющих доспехах. Её последователи клянутся быть честными, храбрыми, милосердными и защищать слабых. Их божественная сила освящает оружие, отгоняет зло и защищает союзников от чар. Это идеальный выбор для благородного защитника, живущего по высоким идеалам.",
  "dnd.s.paladin.glory": "Клятва славы — подкласс паладина, стремящегося к героическим подвигам, достойным легенд. Такие паладины вдохновляются мифическими героями и совершенствуют тело и дух ради великих свершений. Их сила делает их быстрыми, атлетичными и воодушевляет союзников. Подкласс подходит для героев эпических саг.",
  "dnd.s.paladin.vengeance": "Клятва мести — подкласс паладина, поклявшегося карать тех, кто совершил тяжкие злодеяния. Такие паладины ставят наказание виновных выше собственной чистоты и готовы на многое ради справедливости. Их сила помогает настигать и преследовать выбранную цель. Подкласс подходит для мрачных, решительных персонажей с личной миссией.",
  "dnd.s.ranger.beastmaster": "Повелитель зверей — подкласс следопыта, связанный узами с верным зверем-спутником. Животное сражается рядом с хозяином, выполняет его команды и растёт в силе вместе с ним. В более новых правилах спутник воплощает первобытную силу природы и может принимать облик сухопутного, морского или летающего зверя. Подкласс идеален для тех, кто мечтает о верном звере рядом.",
  "dnd.s.ranger.gloomstalker": "Сумрачный охотник — подкласс следопыта, чувствующий себя как дома во тьме. Такие следопыты охотятся в подземельях и глубоких тенях, становясь почти невидимыми для тех, кто полагается на тёмное зрение. В начале боя они действуют стремительно, нанося первый удар раньше врагов. Подкласс подходит для скрытных и смертоносных охотников.",
  "dnd.s.ranger.hunter": "Охотник — подкласс следопыта, посвятивший себя защите мира от чудовищ и других опасностей. Охотники выбирают приёмы, помогающие против определённых угроз: одиночных гигантов, орд врагов или ловких противников. Они хладнокровны, внимательны и стремятся к максимальной эффективности. Это гибкий и понятный путь для персонажа-стража границ.",
  "dnd.s.rogue.arcanetrickster": "Мистический ловкач — подкласс плута, дополняющий воровские навыки магией волшебников. Такие плуты используют иллюзии и очарование, а их невидимая волшебная рука помогает красть и отвлекать на расстоянии. Это хитрый мастер на все руки, который сочетает скрытность с магическими фокусами. Подходит для озорных и изобретательных персонажей.",
  "dnd.s.rogue.inquisitive": "Сыщик — подкласс плута, мастер расследований, наблюдательности и разоблачения лжи. Такие плуты замечают мельчайшие детали, читают людей и видят насквозь обман и маскировку. В бою они используют свою проницательность, чтобы находить слабые места противника. Подкласс из «Руководства Занатара» идеален для детективных и интриганских кампаний.",
  "dnd.s.rogue.swashbuckler": "Дуэлянт — подкласс плута, мастер изящного фехтования и дерзких выходок. Такие плуты прекрасно сражаются один на один, быстро отходят после атаки и полагаются на обаяние и удаль. Им не нужна помощь союзников, чтобы найти слабое место противника. Подкласс из «Руководства Занатара» идеален для персонажей в духе пиратов и романтичных авантюристов.",
  "dnd.s.sorcerer.aberrant": "Аберрантное чародейство — подкласс чародея, чья сила происходит от соприкосновения с чуждыми силами Дальнего Царства или существами вроде пожирателей разума. Такие чародеи владеют телепатией и психической магией, а их тела могут приобретать странные черты. Им близки темы чужеродности и внутренней борьбы. Подкласс развивает идеи Aberrant Mind из «Котла Таши».",
  "dnd.s.sorcerer.draconic": "Драконья кровь — подкласс чародея, чья магия унаследована от предка-дракона. Со временем у таких чародеев появляется чешуя, крепкое здоровье и даже крылья, а заклинания стихии предков становятся особенно мощными. Они горды и величественны, как их прародители. Подкласс подходит для ярких, властных магов.",
  "dnd.s.sorcerer.storm": "Штормовое колдовство — подкласс чародея, чья сила рождена из стихии ветра и бурь. Такие чародеи окружены порывами ветра, легко перемещаются по воздуху и управляют громом и молниями. Многие из них связаны с морем или стихийным планом воздуха. Подкласс из «Руководства Занатара» подходит для энергичных, неукротимых персонажей.",
  "dnd.s.sorcerer.wildmagic": "Дикая магия — подкласс чародея, чья сила рождена из хаоса и непредсказуема. Колдовство такого чародея может вызвать неожиданные всплески: от безобидных до разрушительных. Им трудно полностью контролировать свою магию, но они умеют обращать удачу себе на пользу. Подкласс подходит для игроков, любящих сюрпризы.",
  "dnd.s.warlock.archfey": "Архифея — покровитель колдуна, могущественное существо из мира фей. Архифеи капризны, непредсказуемы и живут по собственным странным законам. Договор с ними дарит магию очарования, иллюзий и мгновенного перемещения. Подкласс подходит для загадочных, игривых и обаятельных персонажей.",
  "dnd.s.warlock.celestial": "Небожитель — покровитель колдуна, существо Верхних планов: ангел, единорог или иная светлая сущность. Колдун, заключивший такой договор, получает доступ к магии света и исцеления, что необычно для этого класса. Такие колдуны часто служат высшему благу, хотя цели их покровителя не всегда понятны смертным. Подкласс хорошо сочетает поддержку союзников с атакующей магией сияния.",
  "dnd.s.warlock.fiend": "Исчадие — покровитель колдуна, существо Нижних планов: демон, дьявол или иная тёмная сила. Договор с ним дарует разрушительную огненную магию и стойкость, но обычно имеет свою цену. Такие колдуны часто балансируют между выгодой и опасностью, пытаясь использовать силу, не потеряв себя. Подкласс подходит для драматичных историй о сделках и искушениях.",
  "dnd.s.warlock.greatoldone": "Великий Древний — покровитель колдуна, непостижимая сущность из далёких звёзд или глубин Дальнего Царства. Его мотивы чужды смертным, а сам он может даже не замечать своего колдуна. Такой договор дарит телепатию, власть над разумом и пугающую магию. Подкласс вдохновлён космическим ужасом и идеален для мрачных, загадочных персонажей.",
  "dnd.s.wizard.enchantment": "Школа очарования — подкласс волшебника, изучающий магию воздействия на разум. Очарователи умеют внушать симпатию, подчинять волю и сбивать врагов с толку, переключая их внимание. Эта магия особенно ценна в переговорах и интригах, но и в бою позволяет вывести противников из строя без кровопролития. Подкласс хорошо подходит для обаятельных и расчётливых персонажей.",
  "dnd.s.wizard.illusion": "Школа иллюзии — подкласс волшебника, посвящённый магии обмана чувств. Иллюзионисты создают ложные образы, звуки и миражи, а со временем учатся делать свои иллюзии почти реальными. В умелых руках эта магия позволяет отвлекать врагов, прятать союзников и решать проблемы без боя. Подкласс требует изобретательности и хорошо подходит игрокам, любящим нестандартные решения.",
  "dnd.s.wizard.transmutation": "Школа преобразования — подкласс волшебника, изучающий изменение материи и энергии. Трансмутаторы превращают одни вещества в другие, меняют облик существ и создают камень трансмутатора, дарующий особые свойства. Их увлекают алхимия и сама природа перемен. Подкласс подходит для любознательных персонажей, видящих мир как материал для экспериментов.",
  "leg.l.al": "Альфа-Легион — XX легион, последний из созданных. Его примархи — близнецы Альфарий и Омегон, долго скрывавшие, что их двое. Легион мастерски использует шпионаж, обман, двойных агентов и культы, а его воины внешне неотличимы друг от друга и называют себя «Альфарием». Почему он перешёл на сторону Хоруса, до сих пор остаётся загадкой, а истинные цели легиона неизвестны. Их символ — многоглавая гидра.",
  "leg.l.ba": "Кровавые Ангелы — IX легион. Их примарх Сангвиний, крылатый и прекрасный, был, пожалуй, самым любимым из сыновей Императора. Он пал в поединке с Хорусом на флагмане магистра войны, но его жертва помогла Императору победить. Легион хранит в генном семени проклятие — Красную Жажду и Чёрную Ярость, наследие гибели примарха. Кровавые Ангелы — благородные, утончённые воины, вечно борющиеся с тьмой внутри себя.",
  "leg.l.da": "Тёмные Ангелы — I легион, первый из созданных Императором. Их примарх Лев Эль'Джонсон вырос в лесах Калибана, охотясь на чудовищ, и стал суровым, замкнутым рыцарем-полководцем. Легион славился дисциплиной и доступом к самому опасному оружию. Во время Ереси он остался верен, но на Калибане часть воинов восстала — Падшие. С тех пор Тёмные Ангелы тайно охотятся на них, оберегая свой позор, и полны секретов.",
  "leg.l.dg": "Гвардия Смерти — XIV легион. Их примарх Мортарион вырос на ядовитом мире Барбарус под властью колдуна-тирана, против которого он восстал. Он ненавидел псайкеров и колдовство, а его легион славился несокрушимой стойкостью. Во время Ереси флот Гвардии Смерти поразила чума в варпе, и, чтобы спасти себя и сыновей, Мортарион отдался Нурглу. Теперь это раздутые, гниющие, но почти неубиваемые воины Чумного Бога.",
  "leg.l.ec": "Дети Императора — III легион, единственный, кому было позволено носить аквилу Императора на доспехах. Их примарх Фулгрим, выросший на мире Хемос, был одержим стремлением к совершенству во всём. Эта гордыня открыла путь порче: через проклятый клинок Фулгрим попал под влияние Слаанеша и предал Императора, убив брата Ферруса Мануса. Легион выродился в поклонников излишеств, вечно ищущих новых ощущений.",
  "leg.l.if": "Имперские Кулаки — VII легион, непревзойдённые мастера обороны. Их примарх Рогал Дорн — непреклонный, честный и упрямый стратег, на которого Император возложил укрепление Терры. Во время Ереси Хоруса именно Дорн руководил обороной Императорского дворца. Кулаки славятся стойкостью, гордостью и неспособностью отступить. После Ереси легион разделился на ордена, включая Чёрных Храмовников и Багровых Кулаков.",
  "leg.l.ih": "Железные Руки — X легион. Их примарх Феррус Манус, выросший на суровом мире Медуза, имел руки, покрытые живым металлом, и презирал слабость плоти. Легион почитает машины и заменяет тело аугметикой, будучи близок к Механикус. Феррус погиб от руки своего брата Фулгрима в резне на Истваане V, и это стало страшным ударом для легиона. С тех пор Железные Руки стали ещё холоднее и безжалостнее.",
  "leg.l.iw": "Железные Воины — IV легион, мастера осадной войны. Их примарх Пертурабо, выросший на Олимпии, был гениальным инженером и полководцем, но чувствовал себя недооценённым: ему постоянно поручали самые тяжёлые и неблагодарные осады. Обида и зависть к Рогалу Дорну привели его на сторону Хоруса. Железные Воины не связаны с одним богом Хаоса, а ценят упорство, расчёт и огневую мощь. Они безжалостны и мстительны.",
  "leg.l.nl": "Повелители Ночи — VIII легион, использующий террор как главное оружие. Их примарх Конрад Кёрз вырос на погружённом во тьму преступном мире Ностромо, где в одиночку наводил порядок страхом, и был мучим пророческими видениями. Легион запугивал целые миры ради их покорности. Предав Империум, Повелители Ночи не служат ни одному богу Хаоса: это налётчики и мучители, движимые жестокостью и местью. Кёрза убила имперская ассасин, как он и предвидел.",
  "leg.l.rg": "Гвардия Ворона — XIX легион, мастера скрытности, засад и молниеносных ударов. Их примарх Коракс вырос в тюрьме-шахте на луне Ликей и возглавил восстание узников, позже переименовавших луну в Освобождение. Он ненавидел тиранию и всегда сражался за угнетённых. Легион почти полностью погиб при Истваане V, и Коракс совершил отчаянные попытки его восстановить. Гвардейцы Ворона — молчаливые, замкнутые воины-тени.",
  "leg.l.sal": "Саламандры — XVIII легион. Их примарх Вулкан вырос на вулканическом мире Ноктюрн и был умелым кузнецом и защитником простых людей. Легион отличается чёрной кожей и красными глазами, любовью к огнемётам и мелтам и мастерством кузнечного дела. Саламандры славятся человечностью: они ставят спасение мирных жителей выше славы. Легион тяжело пострадал при Истваане V, но выжил и остался верен.",
  "leg.l.soh": "Сыны Хоруса — XVI легион, изначально называвшийся Лунными Волками. Их примарх Хорус Луперкаль, выросший на мире-улье Хтония, был любимым сыном Императора и получил титул магистра войны. Но, сражённый ранением и обманутый силами Хаоса, Хорус поднял мятеж, расколовший Империум, — Ересь Хоруса. Он пал в поединке с Императором на своём флагмане. Позже легион был переименован в Чёрный легион под началом Абаддона Разорителя.",
  "leg.l.sw": "Космические Волки — VI легион. Их примарх Леман Русс вырос среди людей ледяного мира Фенрис и стал неистовым, прямодушным воином-королём. Легион, известный как «Волки Фенриса», был палачом Императора, призванным для самых жёстких задач. Именно Волки обрушились на Просперо, мир Тысячи Сынов. Они отвергают многие условности Кодекса, сохраняя дикую, шумную культуру скальдов, рун и пиров, но преданы Империуму до конца.",
  "leg.l.ts": "Тысяча Сынов — XV легион, легион колдунов. Их примарх Магнус Красный — одноглазый великан и могущественнейший псайкер, ищущий знания на родном мире Просперо. Пытаясь предупредить Императора о предательстве Хоруса, Магнус колдовством разрушил защиту Терры. Император отправил Космических Волков, и Просперо был сожжён. Отчаявшись, Магнус отдался Тзинчу. Позже колдун Ариман наложил Рубрику, превратившую большую часть легиона в прах в доспехах.",
  "leg.l.um": "Ультрамарины — XIII легион, самый многочисленный во время Ереси Хоруса. Их примарх Робаут Гиллиман — рассудительный правитель и гениальный организатор, создавший процветающее царство Ультрамар с центром на Макрагге. После Ереси он написал Кодекс Астартес, разделив легионы на ордена. Ультрамарины стали образцом для космодесанта. Пробуждённый спустя десять тысяч лет, Гиллиман вновь ведёт Империум.",
  "leg.l.wb": "Несущие Слово — XVII легион. Их примарх Лоргар, выросший на теократическом мире Колхида, был глубоко религиозен и почитал Императора как бога. Император публично осудил его за это, заставив легион преклонить колени на руинах сожжённого города Монархия. Униженный, Лоргар нашёл новых богов — силы Хаоса — и стал одним из главных зачинщиков Ереси. Несущие Слово — фанатичные проповедники Хаоса Неделимого.",
  "leg.l.we": "Пожиратели Миров — XII легион. Их примарх Ангрон был рабом-гладиатором на мире Нуцерия, где ему вживили Гвозди Мясника — имплант, вызывающий неудержимую ярость и отнимающий радость. Император забрал его, оставив товарищей погибать, и Ангрон так этого и не простил. Легион перенял импланты и стал ордой берсерков. В Ереси Хоруса они присоединились к предателям, а затем стали служителями Кхорна, и Ангрон вознёсся как демон-принц.",
  "leg.l.ws": "Белые Шрамы — V легион, лучшие мастера стремительной войны. Их примарх Джагатай-хан вырос среди кочевых племён степного мира Чогорис и привил легиону культуру всадников, чести и братства. Белые Шрамы предпочитают быстрые налёты на байках и скиммерах. В Ереси Хоруса они колебались, но остались верны и прорвались на помощь Терре. Их часто недооценивают как «дикарей», хотя это утончённые и гордые воины.",
  "leg.lost": "II и XI легионы — два утраченных легиона, сведения о которых были полностью стёрты из имперских архивов ещё до Ереси Хоруса. Неизвестны ни их названия, ни имена их примархов, ни то, что с ними случилось. Даже сами примархи обходят эту тему молчанием. Существует множество слухов и теорий — о предательстве, неудачных экспериментах или гибели в бою, — но официально Games Workshop намеренно оставляет эту тайну нераскрытой.",
  "ow.grudges": "Книга обид — главная летопись дворфов, в которую записывается каждое нанесённое им оскорбление, предательство и долг. Великую книгу обид хранит верховный король в Караз-а-Карак, а у отдельных крепостей и кланов есть свои. Обида считается погашенной только после достойного возмездия или возмещения, и тогда её вычёркивают. Многие записи старше тысячи лет и касаются эльфов, орков и скавенов. Для дворфов это вопрос чести, а не просто память о прошлом.",
  "ow.r.beast": "Зверолюды — рогатые дети Хаоса, полулюди-полузвери, обитающие в глухих лесах Старого Света. Они ненавидят цивилизацию и стремятся уничтожить всё, что создано людьми, сжигая деревни и оскверняя святыни. Их стада ведут могучие вожди, а шаманы читают волю тёмных богов у священных камней своих стад. Зверолюды воплощают первобытную дикость и звериную ярость Хаоса.",
  "ow.r.bret": "Бретония — рыцарское королевство Старого Света, построенное на идеалах чести, куртуазности и почитания Владычицы Озера. Его основу составляют благородные рыцари — от странствующих до рыцарей Грааля, испивших из священной чаши. Чародейки-Пророчицы хранят тайны Владычицы. При всём блеске рыцарства крестьянство живёт в нищете и бесправии, а за лоском чести скрывается жёсткое неравенство.",
  "ow.r.cathay": "Катай — великая империя Дальнего Востока, которую Total War: Warhammer III впервые подробно показала. Ею правит Небесный Император-Дракон вместе с Лунной Императрицей, а их дети-драконы, принимающие человеческий облик, ведут армии. Общество держится на гармонии инь и ян — земной силы и небесной магии. Катай охраняет Великий Бастион, огромную стену против Хаоса, и выставляет нефритовых воинов, небесных стражей и боевые воздушные фонари.",
  "ow.r.cd": "Дворфы Хаоса — ветвь дворфов, павшая в изоляции на Тёмных землях и поклоняющаяся быкоподобному богу Хашуту. Их столица Жарр-Наггрунд — огромная зиккурат-кузница посреди вулканической пустоши. Дворфы Хаоса — безжалостные инженеры и колдуны-демонсмиты, создающие демонические машины. Их промышленность держится на бесчисленных рабах, а с течением времени чародеи буквально каменеют от своей магии.",
  "ow.r.de": "Тёмные эльфы (Друкхи) — эльфы, отколовшиеся от сородичей после Раскола и бежавшие в холодный Наггарот. Ими правит Король-Чародей Малекит, считающий себя законным владыкой Ультуана, и его мать Морати. Их общество построено на жестокости, рабстве и культе бога убийства Каина. Тёмные эльфы прославились набегами на чёрных ковчегах, ведьмами-эльфийками и коварством. Их вечная цель — месть Высшим эльфам.",
  "ow.r.dwarf": "Дворфы — древний, гордый и упрямый народ, живущий в горных крепостях-кархах под горами Края Мира. Некогда их империя процветала, но войны, землетрясения и нашествия орков и скавенов отняли большую часть их владений. Дворфы — непревзойдённые кузнецы, инженеры и мастера рун, почитающие предков и ценящие золото, пиво и данное слово. Они никогда не забывают обид и всё записывают в Книгу обид.",
  "ow.r.emp": "Империя — крупнейшее человеческое государство Старого Света, основанное Зигмаром, вождём, объединившим племена людей и затем почитаемым как бог. Это союз провинций под властью избираемого императора с центром в Альтдорфе. Империя опирается на государственные войска, рыцарские ордена, пороховое оружие, паровые танки и колдунов из Коллегий Магии. Раздираемая политикой и угрозами со всех сторон, она остаётся главным оплотом людей против Хаоса.",
  "ow.r.he": "Высшие эльфы — древняя и гордая раса с острова Ультуан, где их предки некогда создали Великий Вихрь, удерживающий магию Хаоса. Ими правит Король-Феникс, а их армии славятся дисциплинированной пехотой, магами и драконьими всадниками. Высшие эльфы ведут бесконечную войну с отколовшимися тёмными сородичами и не забыли древнюю распрю с дворфами. Их часто считают высокомерными, но они остаются одними из главных защитников мира.",
  "ow.r.kislev": "Кислев — суровое северное царство, первым встречающее орды Хаоса с Пустошей. В Total War: Warhammer III им правит Ледяная королева царица Катарина, могущественная ведьма льда, тогда как патриарх Костальтин возглавляет ревностных почитателей бога-медведя Урсуна. Кислевиты почитают богов Урсуна, Дажа и Тора, а их армии сочетают пехоту-кошаков, крылатых уланов, боевых медведей и ведьм льда. Это народ стойкости, веры и сурового выживания.",
  "ow.r.liz": "Люди-ящеры — древняя раса из джунглей Люстрии, созданная Древними для исполнения их Великого плана. Ими правят мудрые жабоподобные маги-слэнны, повелевающие могущественной магией. Им служат воины-сауруси, ловкие сцинки и огромные ящеры вроде стегадонов. Люди-ящеры — одни из старейших противников Хаоса, хотя ради своего плана они бывают холодно безразличны к судьбам других народов.",
  "ow.r.ogre": "Огры — огромные, прожорливые существа из Королевств огров в Горах Скорби. Их жизнь вращается вокруг еды: они поклоняются Великой Пасти и готовы съесть почти что угодно. Огры охотно нанимаются в армии любой расы, лишь бы платили и кормили, а их правитель — тиран, самый большой и сильный из всех. Грубые и простодушные, они при этом разумны и грозны в бою, сметая врагов своей массой.",
  "ow.r.orc": "Орки и гоблины — зеленокожие, самые многочисленные и неуёмные враги цивилизации Старого Света. Орки — крупные, сильные и живущие ради драки, гоблины — мелкие, трусоватые и коварные, но стая их не менее опасна. Время от времени великий вождь объединяет племена в Вааагх! и обрушивает их на соседей. Ими движут жажда сражений и грабежа, а не замыслы, и потому они непредсказуемы и смешны — и смертельно опасны.",
  "ow.r.skaven": "Скавены — раса разумных крысолюдей, живущая в огромной сети туннелей под землёй Старого Света, — Подземной империи. Их столица — Скейвенблайт, а власть принадлежит Совету Тринадцати. Скавены неимоверно многочисленны, трусливы и вероломны, вечно плетут интриги друг против друга. Используя камень искажения, они создают безумные изобретения и чуму. Большинство людей считает их лишь сказкой.",
  "ow.r.tk": "Цари гробниц — древние правители Нехекхары, страны, напоминающей Древний Египет. Их цивилизация погибла, когда великий некромант Нагаш совершил ритуал, поднявший мёртвых всей страны. Пробуждённые цари гробниц обнаружили, что обещанный рай оказался обманом, и правят теперь армиями скелетов, ожившими статуями и колесницами. Они высокомерны, привязаны к древним традициям и ненавидят Нагаша и вампиров.",
  "ow.r.vamp": "Вампиры (Графы-вампиры) — бессмертные владыки нежити Сильвании и других тёмных земель Старого Света. Род вампиров восходит к Неферате и её последователям из древней Ламии. Они повелевают армиями скелетов, зомби и призраков, поднятых некромантией. Самые известные — династия фон Карштайнов, когда-то пытавшаяся завоевать Империю. Аристократичные, жестокие и вечно голодные, они видят в живых лишь скот и подданных.",
  "ow.r.we": "Лесные эльфы — потомки эльфов, оставшихся в Старом Свете после ухода сородичей на Ультуан. Они живут в волшебном лесу Атель Лорен в союзе с его древесными духами и разделяют власть между Королевой Ариэль и Королём Орионом. Лесные эльфы — мастера лука и засады, яростно защищающие свой лес от любого вторжения. Чужаков они не жалуют, а их помыслы связаны прежде всего с сохранением природного равновесия.",
  "ow.r.woc": "Воины Хаоса — избранные смертные северных Пустошей Хаоса, посвятившие себя тёмным богам. Облачённые в тяжёлую броню, они ищут славы и благосклонности богов, надеясь однажды стать демонами-принцами. Их ведут могучие лорды, такие как Архаон Вечноизбранный, и за ними идут племена северян и демоны. Воины Хаоса раз за разом устремляются на юг, грозя гибелью всему Старому Свету.",
  "wh.f.aeldari": "Эльдары (Аэльдари) — древняя, утончённая и гордая раса, некогда правившая галактикой. Их империя пала, когда бездна их излишеств породила Слаанеша, и с тех пор они — вымирающий народ. Большинство живёт на огромных кораблях-мирах, держа себя в узде строгими Путями, а их души хранят камни духа. Эльдары — искусные псайкеры и воины с передовыми технологиями, но их мало, и каждая потеря невосполнима. Ведомые провидцами, они часто действуют загадочно и высокомерно.",
  "wh.f.csm": "Космодесант Хаоса — космодесантники, предавшие Императора и отдавшиеся силам Хаоса. Ядро их составляют девять легионов-предателей, восставших во время Ереси Хоруса и отступивших в Око Ужаса, а также позднейшие ренегаты. Десять тысяч лет они ведут Долгую войну против Империума, движимые ненавистью, жаждой мести и даров тёмных богов. Многие из них — ветераны, лично помнящие эпоху Великого крестового похода.",
  "wh.f.dmech": "Тёмный механикус — техножрецы-отступники, отринувшие догмы Марса и обратившиеся к Хаосу. Раскол произошёл во время Ереси Хоруса, когда часть Механикус поддержала предателей. Тёмные магосы без ограничений экспериментируют с запретными технологиями, сплавляя машины с плотью и демонами. Они создают демонические машины и служат легионам-предателям, особенно Железным Воинам. Для Империума они — воплощение технологии, вышедшей из-под контроля.",
  "wh.f.drukhari": "Тёмные эльдары (Друкхари) — потомки той части эльдаров, что не отказалась от излишеств и после Падения. Они живут в Комморре — огромном городе в паутине, скрытом от варпа. Чтобы Слаанеш не пожрал их души, они питаются чужими страданиями, совершая налёты на другие миры ради пленников и рабов. Их общество построено на интригах, жестокости и борьбе за власть между кабалами, культами ведьм и гемункулами.",
  "wh.f.gk": "Серые Рыцари — тайный орден космодесанта, созданный для одной цели: истребления демонов. Каждый из них — псайкер, чья душа закалена так, чтобы противостоять порче варпа. Они базируются на скрытом спутнике Титан и действуют в тесной связи с Ордо Маллеус Инквизиции. Серебристая броня, освящённое оружие и молитвы-обереги делают их самым грозным оружием Империума против сил Хаоса. Об их существовании знают очень немногие.",
  "wh.f.harlequins": "Арлекины — загадочные эльдары-странники, служители Смеющегося Бога Цегораха, единственного эльдарского бога, пережившего рождение Слаанеша. Они путешествуют по паутине и разыгрывают священные танцы-представления, пересказывающие историю и мифы своего народа. Арлекины свободно бывают и на кораблях-мирах, и в Комморре, связывая разрозненные ветви эльдаров. В бою это молниеносные, акробатичные воины в пёстрых масках, хранящие тайну Чёрной библиотеки.",
  "wh.f.ig": "Имперская гвардия (Астра Милитарум) — огромная армия Империума из миллиардов обычных солдат, набираемых на бесчисленных планетах. Их сила — не в выучке и снаряжении, а в численности, танках, артиллерии и готовности стоять до конца. Лазганы, «Леман Руссы» и комиссары, расстреливающие трусов, стали её символами. Гвардейцы — простые люди перед лицом кошмаров галактики, и их стойкость — одна из главных опор Империума.",
  "wh.f.mech": "Адептус Механикус — жречество Бога-Машины с центром на Марсе, хранители технологий Империума. Техножрецы почитают машины как вместилища духа и Омниссию — воплощение Бога-Машины, которым они считают Императора. Они постепенно заменяют плоть аугметикой, ведь «плоть слаба». Механикус создают оружие, корабли и титанов, но больше ищут утраченные древние знания, чем изобретают новое. Союз Марса и Терры — основа существования Империума.",
  "wh.f.necrons": "Некроны — древняя раса, некогда бывшая смертными некронтир. Ради бессмертия и войны с древними они отдали свои тела звёздным богам К'тан и стали существами из живого металла. Шестьдесят миллионов лет они спали в гробницах-мирах, а теперь пробуждаются, чтобы вернуть галактику себе. Многие некроны утратили разум, но их аристократия сохранила личности, амбиции и причуды. Некроны почти невозможно уничтожить: павшие воины восстанавливаются или телепортируются прочь.",
  "wh.f.orks": "Орки — зеленокожая раса воинственных существ, распространённая по всей галактике. Они живут ради драки и искренне радуются любой войне, а размер и сила определяют, кто главный. Орки размножаются спорами, почти невосприимчивы к боли и собирают оружие и технику из мусора — и, что удивительно, всё это работает, потому что они в это верят. Их коллективная психическая энергия усиливается, когда их много. Несмотря на комичный облик, орки — одна из самых опасных угроз галактике.",
  "wh.f.sm": "Космодесант (Адептус Астартес) — генетически усиленные сверхлюди-воины Империума Человечества, его самая известная элитная сила. Каждый космодесантник проходит имплантацию органов, полученных из генного семени примарха своего ордена, и облачается в силовую броню. Ордена насчитывают около тысячи бойцов и обычно следуют Кодексу Астартес. Их почитают как Ангелов Смерти — непоколебимых защитников человечества, но они далеки от обычных людей и нередко внушают страх.",
  "wh.f.sob": "Сёстры битвы (Адепта Сороритас) — воинствующие ордена Экклезиархии, имперской церкви, почитающей Бога-Императора. Это обычные люди без генетических усилений, но их несокрушимая вера, по преданию, способна творить чудеса на поле боя. Они вооружены болтерами, огнемётами и мелтами и беспощадны к еретикам, мутантам и ведьмам. Сёстры воплощают религиозный пыл Империума — одновременно вдохновляющий и пугающий.",
  "wh.f.tau": "Тау — молодая и быстро развивающаяся раса, строящая Империю Тау под лозунгом Высшего Блага. Их общество разделено на касты — огня, земли, воздуха, воды и эфирных, — причём эфирные правят остальными. Тау полагаются на передовую технику: боевые скафандры, дальнобойное оружие и дронов, предпочитая стрельбу ближнему бою. Они охотно принимают в свою империю другие народы, но за идеализмом Высшего Блага многие видят тоталитарный контроль.",
  "wh.f.tyranids": "Тираниды — инопланетный рой, пришедший из-за пределов галактики. Ульи-флоты пожирают целые планеты, перерабатывая всю органику в биомассу для создания новых организмов. Каждое существо роя, от мелких гаунтов до гигантских тиранов-улья, связано с Разумом Улья — коллективным сознанием, порождающим ужасающую Тень в варпе. Тираниды быстро адаптируются к любому противнику и не знают ни страха, ни переговоров.",
  "wh.waaagh": "WAAAGH! — одновременно боевой клич орков, их великий завоевательный поход и психическая энергия, которую они излучают. Когда появляется особенно сильный и удачливый вождь, к нему стекаются банды со всех сторон, и орда начинает лавиной катиться по галактике. Чем больше орков и чем сильнее их азарт, тем мощнее поле WAAAGH!, питающее их шаманов и даже заставляющее работать их ненадёжную технику. Крупный WAAAGH! способен смести целые сектора Империума.",
  "wi.g.aard": "Аард — ведьмачий знак телекинеза, выпускающий мощную волну силы. Он отбрасывает и оглушает противников, сбивает их с ног, а также позволяет разрушать хрупкие стены и препятствия и гасить огонь. Это один из самых простых и универсальных знаков, полезный и в бою, и при исследовании мира. В «Ведьмаке 3» усовершенствованный Аард может бить по площади вокруг ведьмака.",
  "wi.g.axii": "Аксий — ведьмачий знак внушения, воздействующий на разум. В бою он ненадолго ошеломляет противника или даже заставляет его сражаться на стороне ведьмака. Вне боя Аксий помогает убеждать собеседников, открывая новые варианты в диалогах. Это тонкий знак контроля, а не силы, работающий хуже против сильной воли.",
  "wi.g.igni": "Игни — ведьмачий знак огня, выпускающий струю или вспышку пламени. Он поджигает врагов, заставляя их гореть и паниковать, и особенно действенен против существ, боящихся огня. Игни также зажигает факелы, жаровни и взрывоопасные газы. Это самый разрушительный из основных знаков, но опасный для неосторожного ведьмака.",
  "wi.g.quen": "Квен — ведьмачий защитный знак, создающий вокруг ведьмака магический щит. Щит поглощает удары, а в усиленной форме может отражать урон на нападающего или восстанавливать здоровье. Это один из самых надёжных знаков для выживания в бою, особенно против сильных противников. Многие игроки «Ведьмака 3» считают его незаменимым.",
  "wi.g.yrden": "Ирден — ведьмачий знак-ловушка: магический символ, начертанный на земле. Он замедляет противников, ступивших в круг, а у призраков и других бесплотных существ отнимает способность исчезать, делая их уязвимыми. Ирден требует подготовки, но незаменим в схватках с призраками и в обороне. В «Ведьмаке 3» его альтернативная форма поражает врагов магическими разрядами.",
  "wi.s.bear": "Школа Медведя — школа ведьмаков, чья крепость Хаэрн Кадух скрыта в горах Амелл. Медведи отличались замкнутостью и самостоятельностью: ведьмаки этой школы часто действовали в одиночку и относились к охоте на чудовищ как к ремеслу. Их стиль строился на силе, выносливости и тяжёлой броне. В «Ведьмаке 3» их снаряжение — самое тяжёлое среди ведьмачьих комплектов.",
  "wi.s.cat": "Школа Кота — школа ведьмаков с самой дурной репутацией. Котов считают неуравновешенными, возможно из-за изменённого обучения или мутаций, и многие из них нанимаются убийцами и наёмниками, не гнушаясь заказов на людей. Они полагаются на скорость, ловкость и лёгкую броню. Постоянной крепости у них, по-видимому, не было или она была утрачена, и члены школы разбрелись по миру. В играх их снаряжение даёт бонусы к быстрым атакам.",
  "wi.s.griffin": "Школа Грифона — школа ведьмаков, основанная Эрландом из Ларвика, с крепостью Каэр Серен на побережье Ковира и Повисса. Грифоны стремились сохранить рыцарский образ ведьмака, служащего людям, а их крепость славилась библиотекой. Они делали упор на знаки и магию больше, чем другие школы. Как и остальные, школа пострадала от гонений на ведьмаков. В «Ведьмаке 3» их снаряжение подходит для игры через знаки.",
  "wi.s.manticore": "Школа Мантикоры — самая загадочная из ведьмачьих школ, действующая далеко на востоке, за пределами Северных королевств и Нильфгаарда. Её история и стиль подробнее описаны в настольной ролевой игре по «Ведьмаку», где школа связана с землями за пустыней Корат. Ведьмаки Мантикоры славятся мастерством в алхимии и ядах. В «Ведьмаке 3» их снаряжение рассчитано на игру через алхимию.",
  "wi.s.viper": "Школа Змеи — школа ведьмаков с крепостью Гортур Гваэд в горах Тир Тохаир на юге, на землях, позже вошедших в Нильфгаард. Самый известный её представитель — Лето из Гулеты, убийца королей из «Ведьмака 2». После упадка школы её последние члены стали служить Нильфгаарду в качестве наёмных убийц. Змеи славились хладнокровием, ядами и смертоносной эффективностью.",
  "wi.s.wolf": "Школа Волка — самая известная школа ведьмаков, базирующаяся в старой крепости Каэр Морхен в горах Каэдвена. Её выпускники — Геральт из Ривии, Весемир, Эскель и Ламберт. Ведьмаки Волка отличаются сбалансированным стилем, сочетающим фехтование, знаки и алхимию. Крепость пострадала в нападении фанатиков, и к временам Геральта школа почти угасла. Её последние члены придерживаются старого кодекса и стараются оставаться нейтральными.",
  "wod.aus.ahroun": "Арун — гару, рождённый под полной луной. Это прирождённые воины, первые в бою против Вирма и защитники септа, наделённые самой высокой Яростью среди ауспиций. Аруны отважны и неукротимы, но их ярость опасна и для своих, а жизнь часто бывает короткой. Их ценят за храбрость и силу, хотя и побаиваются их вспыльчивости.",
  "wod.aus.galliard": "Галлиард — гару, рождённый под почти полной, растущей луной. Это барды, сказители и хранители памяти, которые воспевают подвиги, передают легенды и вдохновляют соплеменников перед боем. Галлиарды страстны, эмоциональны и часто становятся душой септа. Их песни и истории сохраняют историю Нации гару для будущих поколений.",
  "wod.aus.philodox": "Филодокс — гару, рождённый под половиной луны, символом равновесия. Это судьи и законники, хранители Литании, которые разрешают споры, следят за честными поединками и выносят приговоры. Филодоксы стремятся видеть обе стороны любого вопроса и судить беспристрастно, даже если это непопулярно. Их уважают за мудрость, хотя порой считают слишком суровыми.",
  "wod.aus.ragabash": "Рагабаш — гару, рождённый под новолунием, когда луна не видна. Это хитрецы, разведчики и шутники, чья роль — задавать неудобные вопросы и проверять традиции на прочность. Им позволено нарушать правила, которые другим не простили бы, ведь так они указывают на слабости общества. Рагабаши начинают с самой низкой Яростью среди всех ауспиций.",
  "wod.aus.theurge": "Теург — гару, рождённый под растущим полумесяцем. Это шаманы и мистики, посредники между оборотнями и миром духов: они ведут переговоры с духами, создают фетиши и проводят обряды. Теургам часто снятся вещие сны, и многие считают их немного отстранёнными от мира. Их Ярость невысока, зато Гнозис силён.",
  "wod.banality": "Банальность — сила неверия, скуки и рационализма, противоположная Гламуру и смертельно опасная для фейри. Значение по шкале от 1 до 10 показывает, насколько подменыш затронут обыденностью: чем оно выше, тем сильнее его фейская природа подавлена, а магия слабеет. Высокая Банальность грозит Забвением — состоянием, при котором фейри забывает, кто он есть. Банальность также служит защитой от чужих чар.",
  "wod.breed.homid": "Хомид — гару, рождённый в человеческом облике от человеческого родителя. Такие оборотни растут обычными людьми и часто узнают о своей природе лишь при первой перемене, что бывает настоящим потрясением. Хомиды хорошо понимают человеческий мир и технологии, но связь с духами у них слабее, чем у волков по рождению. Сегодня это самая многочисленная порода гару.",
  "wod.breed.lupus": "Люпус — гару, рождённый волком от волчьего родителя. Такие оборотни растут в стае, мыслят инстинктами и острее других чувствуют природу и мир духов, поэтому их Гнозис изначально высок. Человеческий мир с его машинами и законами им чужд и непонятен. С сокращением диких волков люпусов становится всё меньше, и многие из них винят в этом людей.",
  "wod.breed.metis": "Метис — дитя запретной связи двух гару, нарушивших Литанию. Такие оборотни рождаются в боевом облике и бесплодны, а каждый несёт врождённое уродство или изъян. В обществе гару метисов нередко считают позором и сторонятся их, но многие вырастают стойкими и мудрыми, ведь им с детства приходится бороться за место среди своих. В отличие от других пород, они растут среди оборотней и знают о своей природе с рождения.",
  "wod.court.seelie": "Благой двор — одна из двух великих политических и философских сторон общества фейри. Его приверженцы чтят традиции, честь, рыцарство, верность слову и защиту слабых, видя в этом основу порядка. Традиционно Благой двор правит в светлую половину года — от Бельтайна до Самайна. Большинство знатных домов ши относится к Благим, хотя в двор входят и простолюдины любых китов.",
  "wod.court.unseelie": "Неблагой двор — вторая великая сторона общества фейри, противопоставляющая себя Благому двору. Неблагие ценят перемены, свободу, страсть и личную честность перед самим собой больше, чем застывшие обычаи. Они не обязательно злы: для них хаос — двигатель обновления Грёзы. По традиции Неблагой двор правит в тёмную половину года — от Самайна до Бельтайна.",
  "wod.demon.a.defilers": "Нереиды — изначальное ангельское имя Дома Осквернителей, Пятого дома. Эти ангелы правили морями, реками и глубинами, а также тайными течениями чувств и стремлений. Они пробуждали в людях любовь к прекрасному, тоску по недостижимому и тягу к творчеству. Имя напоминает об их связи с водой и вдохновением, тогда как человеческое прозвище отражает то, как Падшие научились пользоваться чужими желаниями.",
  "wod.demon.a.devils": "Глашатаи — изначальное ангельское имя Дома Дьяволов, Первого дома, данное им при Творении. Глашатаи были вестниками Создателя: они несли Его слово и волю ангельскому воинству и всему мирозданию, а их голос и свет вселяли благоговение. Это имя напоминает о том, что Дьяволы когда-то были самыми близкими к престолу Небес. Многие Падшие до сих пор предпочитают его прозвищу, данному людьми.",
  "wod.demon.a.devourers": "Дом Дикой Природы — изначальное ангельское имя Дома Пожирателей, Шестого дома. Его ангелы заботились о зверях, растениях и живой плоти, вкладывая в мир первозданную силу и инстинкты. Они были пастырями всего, что растёт, бегает и охотится. Человеческое прозвище «Пожиратели» отражает свирепость и голод, которые возобладали в доме после Падения.",
  "wod.demon.a.fiends": "Провидцы — изначальное ангельское имя Дома Извергов, Четвёртого дома. Эти ангелы были хранителями небесных светил: по звёздам они прокладывали и читали пути судьбы, видя узоры, что связывают прошлое и будущее. Имя отражает их дар предвидения и роль толкователей замысла Творца. После восстания они открыли эти тайны человечеству.",
  "wod.demon.a.malefactors": "Искусники — изначальное ангельское имя Дома Преступников, Третьего дома. Искусники были ангелами земли и мастерами Творения: они возводили горы, прокладывали русла рек и наполняли недра металлами и камнями. Это имя подчёркивает их роль созидателей и ремесленников, а не разрушителей. Своё человеческое прозвище дом получил за оружие и артефакты, выкованные в войне против Небес.",
  "wod.demon.a.scourges": "Ангелы-Хранители — изначальное ангельское имя Дома Кнутов, Второго дома. Эти ангелы были хранителями небесного свода и дыхания жизни: они оберегали живых существ, приносили ветра и исцеляли творения. Имя отражает их первоначальную задачу защитников и целителей. Позднее имя «Кнуты» пристало к дому из-за болезней и бедствий, которые насылали некоторые из них после Падения.",
  "wod.demon.a.slayers": "Жнецы — изначальное ангельское имя Дома Убийц, Седьмого дома. Эти ангелы были ангелами смерти: они бережно отделяли души от тел в конце жизни и провожали их дальше, следя за естественным круговоротом. Имя подчёркивает, что смерть была для них не убийством, а исполнением долга. Людское прозвище «Убийцы» появилось уже после Падения, когда смерть стала оружием в их руках.",
  "wod.demon.defilers": "Осквернители — Пятый дом Падших, ангелы морей, глубин и вод, связанные с чувствами, мечтами и стремлениями. Они вдохновляли людей на искусство и любовь к красоте, а после Падения научились пробуждать и использовать чужие желания. Осквернители переменчивы как вода, обаятельны и изобретательны. Их Знания — Знание Желания, Знание Бурь и Знание Метаморфоз.",
  "wod.demon.devils": "Дьяволы — Первый дом Падших, некогда вестники Небес, возвещавшие волю Творца всему мирозданию. В восстании их возглавлял сам Люцифер, и многие Дьяволы были полководцами и идеологами мятежа. Это прирождённые лидеры и ораторы, способные внушать благоговение и вести за собой толпы. Их Знания — Знание Небожителей, Знание Пламени и Знание Сияния.",
  "wod.demon.devourers": "Пожиратели — Шестой дом Падших, ангелы дикой природы, отвечавшие за зверей, растения и плоть всех живых существ. Они пестовали первобытную силу жизни и научили людей охоте и выживанию. После Падения Пожиратели воплотили неукротимую ярость и голод дикой природы. Их Знания — Знание Зверей, Знание Плоти и Знание Дикой природы.",
  "wod.demon.fiends": "Изверги — Четвёртый дом Падших, ангелы небесных светил, читавшие и прокладывавшие пути судьбы по звёздам. Они видели узоры, связывающие все события, и открыли людям знание о будущем. После восстания Изверги стали провидцами, мастерами судьбы и мистических врат. Их Знания — Знание Света, Знание Узоров и Знание Порталов.",
  "wod.demon.malefactors": "Преступники — Третий дом Падших, ангелы земли, создававшие горы, реки и всё, что покоится в земной толще. Они были величайшими мастерами Творения, а после восстания стали кузнецами оружия и артефактов для войны с Небесами. Преступники практичны, терпеливы и ценят созданное руками. Их Знания — Знание Земли, Знание Кузнечного дела и Знание Путей.",
  "wod.demon.scourges": "Кнуты — Второй дом Падших, ангелы небесного свода и дыхания жизни, которые оберегали всё живое и разносили ветра. Они вдохнули жизнь в творения Создателя и исцеляли их. После восстания часть Кнутов обратилась к насылаемым болезням и чуме, отсюда их имя. Их Знания — Знание Пробуждения, Знание Небесного Свода и Знание Ветра.",
  "wod.demon.slayers": "Убийцы — Седьмой дом Падших, ангелы смерти, которые провожали души и следили за естественным концом всякой жизни. До восстания смерть была лишь переходом, и они бережно исполняли этот долг. После Падения Убийцы стали повелителями распада, призраков и границы между мирами. Их Знания — Знание Смерти, Знание Сфер и Знание Душ.",
  "wod.fac.cryptic": "Скрытные — фракция Падших, стремящихся понять истинные причины всего случившегося. Они задаются вопросами о замысле Творца, о том, почему Он допустил восстание, и о том, что произошло с миром за тысячелетия их заточения. Скрытные собирают знания, древние тексты и тайны, веря, что ответы укажут путь. Это одна из самых загадочных фракций.",
  "wod.fac.faustian": "Фаустианцы — фракция Падших, считающих человечество ключом к победе и спасению. Они собирают Веру смертных через договоры и слуг, создавая сети последователей и влияния. Одни фаустианцы видят в людях лишь ресурс, другие искренне хотят возвысить их и вернуть им утраченную божественную искру. Эта фракция отличается особым прагматизмом.",
  "wod.fac.luciferan": "Люцифериане — фракция Падших, сохранивших верность Люциферу и продолжающих его дело. Они верят, что Утренняя Звезда вернётся, и готовят армию к возобновлению войны против Небес. Люцифериане ценят дисциплину, иерархию и старые воинские традиции восстания. Их цель — победа в великом противостоянии, начатом ещё до начала времён.",
  "wod.fac.ravener": "Жаждущие — фракция Падших, пришедших к выводу, что их проклятие вечно и искупления не будет. Если им не суждено вернуться к Творцу, они хотят уничтожить само Творение, отомстив Богу и прекратив собственные муки. Жаждущие — самая опасная и нигилистичная группа, которой опасаются даже другие демоны. Многие из них глубоко поглощены Мукой.",
  "wod.fac.reconciler": "Миротворцы — фракция Падших, стремящихся исправить вред, причинённый миру войной и Падением. Они хотят восстановить Землю в её первозданной красоте и вновь стать заботливыми хранителями Творения, которыми были когда-то. Одни ищут примирения с Небесами, другие — просто искупления перед людьми и природой. Миротворцы склонны к созиданию и милосердию, хотя их методы не всегда мягки.",
  "wod.faith": "Вера — мера духовной силы демона, которую он черпает из веры и преданности смертных. Значение от 1 до 10 показывает, насколько велик его запас этой силы и насколько мощными могут быть его воззвания. Вера тратится на усиление Знаний, принятие апокалиптического облика и заключение договоров, а восполняется через поклонение, молитвы и пакты со смертными. Высокая Вера делает Падшего грозным, но и привлекает внимание соперников.",
  "wod.fey.boggan": "Богганы — трудолюбивые домашние фейри, похожие на невысоких коренастых хозяев с ловкими руками. Они находят радость в простой работе: уборке, ремесле, готовке, а ещё обожают слухи и всегда знают, что творится по соседству. Богганы охотно помогают скромным и нуждающимся, но с трудом терпят спесь и праздность. Их слабость — неспособность бросить начатое дело или пройти мимо чужой беды.",
  "wod.fey.clurichaun": "Клуриконы — родичи лепреконов из ирландского фольклора, весёлые задиры, любители выпивки, песен и хорошей драки. Они обаятельны, удачливы и щедры к друзьям, но мгновенно вспыхивают от обиды. Клуриконы известны тягой к проказам и умением находить спрятанное. Их слабость — вспыльчивость: стоит задеть их гордость, и они уже не могут удержаться от ссоры или потасовки.",
  "wod.fey.eshu": "Эшу — фейри-странники и рассказчики, чьи корни уходят к мифам Африки, Индии и Ближнего Востока. Они неутомимо ищут приключений и историй, а их дар позволяет в пути всегда попадать туда, где происходит что-то важное. Эшу — превосходные сказители и знатоки дорог, высоко ценящие гостеприимство. Их слабость — безрассудство: они почти не способны отказаться от рискованного вызова или азартного пари.",
  "wod.fey.ghille": "Гилли Ду — фейри лесов и растительности, восходящие к шотландским и ирландским легендам о духах деревьев. Их химерический облик напоминает живую зелень: кожу, похожую на кору, волосы из листьев или мха. Они защищают дикие рощи и глубоко чувствуют смену времён года, которая влияет на их облик и настроение. В городах среди камня и асфальта им неуютно, поэтому Гилли Ду редко надолго покидают природу.",
  "wod.fey.nocker": "Нокеры — ворчливые гениальные изобретатели и мастера, способные создать почти любой механизм, в том числе химерический. Они славятся скверным характером и цветистыми ругательствами, которыми сыплют за работой. Проклятие нокеров в том, что ни одно их творение не бывает совершенным: в каждом есть скрытый изъян, и они знают об этом. Несмотря на брюзжание, хороший нокер — бесценный союзник любого подменыша.",
  "wod.fey.pooka": "Паки — весёлые фейри-оборотни, каждый из которых связан с определённым животным: кошкой, лисой, вороном, зайцем и т. п. Они способны принимать облик своего зверя и перенимают его повадки. Паки — неисправимые шутники, и их главная слабость в том, что они почти не могут говорить правду прямо: вместо этого они лгут, недоговаривают или отвечают загадками. Тем не менее друзья знают, что за выдумками часто скрывается дружеское участие.",
  "wod.fey.redcap": "Красные Шапки — грубые и опасные фейри, известные своей способностью и стремлением сгрызть практически что угодно, от еды до металла. Их облик и манеры пугают окружающих, и они охотно пользуются этим, чтобы запугивать и самоутверждаться. Красные Шапки ценят силу и бесстрашие, а знать часто держит их как наёмных бойцов. Их слабость — скверная репутация: другие фейри относятся к ним с подозрением и неприязнью.",
  "wod.fey.satyr": "Сатиры — страстные фейри с козлиными ногами и рогами, чья природа связана с дикой природой, музыкой и праздником. Они живут ярко и порывисто, ценят вино, танцы, искусство и философские беседы. Сатиры славятся выносливостью и умением зажигать в других вдохновение и радость. Их слабость — трудность в обуздании собственных порывов: поддавшись настроению, они легко забывают о долге и осторожности.",
  "wod.fey.selkie": "Селки — морские фейри, способные превращаться в тюленей с помощью волшебной тюленьей шкуры. Они живут у побережий, любят море и его обитателей и часто выступают защитниками океана от загрязнения и охотников. Шкура — источник их силы и одновременно уязвимость: тот, кто похитит её, получает власть над селки. Утратив шкуру навсегда, селки лишается связи с морем.",
  "wod.fey.sidhe": "Ши — благородные фейри, аристократия Грёзы, отличающиеся неземной красотой и величественной осанкой. Большинство из них вернулось из Аркадии лишь в 1969 году, во время так называемого Возрождения, и заявило права на власть, что привело к Войне Согласия с простолюдинами. Ши хорошо разбираются в этикете, интригах и искусстве правления. Их слабость — особая уязвимость к Банальности: столкновение с обыденностью ранит их сильнее, чем других.",
  "wod.fey.sluagh": "Слуаги — бледные, худые и молчаливые фейри, хранители тайн и знатоки всего забытого и мрачного. Они живут на чердаках, в подвалах и заброшенных домах, умеют протискиваться в невероятно узкие щели и обладают острейшими чувствами. Слуаги общаются почти исключительно шёпотом: громкая речь даётся им с огромным трудом. Другие фейри побаиваются их, но ценят как добытчиков секретов и посредников с миром призраков.",
  "wod.fey.troll": "Тролли — могучие фейри огромного роста, прославленные силой, стойкостью и верностью. Они служат телохранителями, стражами и воинами, а их слово крепче камня. Тролли ценят честь и долг превыше всего и редко нарушают клятвы. Их слабость прямо связана с этим: если тролль изменит обязательству или своему господину, его сверхъестественная сила покидает его, пока он не искупит вину.",
  "wod.gen": "Поколение показывает, сколько ступеней отделяет вампира от Каина, первого из Сородичей: Каин — первое поколение, а каждое Становление прибавляет единицу к поколению создателя. Чем ниже поколение, тем гуще кровь: такой вампир дольше удерживает больше крови, может развивать черты сверх обычных пределов и труднее поддаётся чужой воле. Большинство современных неонатов принадлежат к 12–13-му поколению, а древние старейшины — к 4–6-му. Понизить своё поколение можно, совершив диаблери — поглотив душу старшего вампира.",
  "wod.glamour": "Гламур — энергия грёз, вдохновения и творчества, сама сущность фейри и источник их магии. Значение показывает, сколько этой силы подменыш способен удерживать: шкала от 1 до 10, где высокий Гламур означает сильную связь с Грёзой. Гламур тратится на кантрипы (применение Искусств) и поддержание химер, а восполняется через искусство, мечты, вдохновение людей и посещение волшебных мест. Без Гламура фейри угасают под натиском обыденности.",
  "wod.gnosis": "Гнозис — духовная сила гару и мера их связи с Геей и миром духов. Его значение обычно лежит от 1 до 10: Гнозис нужен, чтобы переходить в Умбру, пробуждать фетиши, применять некоторые Дары и общаться с духами. Ярость и Гнозис противоположны: в гневе оборотень теряет связь с духами. Изначальный Гнозис зависит от породы — выше всего он у люпусов, ниже всего у хомидов.",
  "wod.house.aesin": "Дом Эйзин — дом ши скандинавских и кельтских корней, возникший из союза воинственных асов и мирных ванов. Большинство его членов принадлежат к Неблагому двору, хотя есть и Благие. Эйзины считают себя стражами мира от угрозы йотунов, строго соблюдают иерархию и свои Девять добродетелей. Они обладают даром говорить с лесными зверями, но смотрят на всех, кроме знати, свысока, что вредит их общению.",
  "wod.house.ailil": "Дом Эйлиль — Неблагой дом ши, известный честолюбием, хитростью и мастерством придворной политики. Его члены видят в интригах естественный порядок вещей и стремятся к власти любыми средствами, умело манипулируя союзниками и соперниками. Эйлили горды, умны и опасны в споре. Многие считают их естественными лидерами Неблагого двора, хотя другие дома относятся к ним с опаской.",
  "wod.house.balor": "Дом Балор — Неблагой дом ши, ведущий род от союза фоморов с Туата Де Дананн. Он устроен как армия и считает себя в постоянной войне, готовясь к Вечной ночи, когда Неблагие должны взять власть. Фоморская кровь даёт Балорам стойкость к холодному железу. Взамен каждый член дома несёт неустранимое уродство — телесное, душевное или эмоциональное.",
  "wod.house.beaumayn": "Дом Бомайн — Благой дом ши, известный как дом прорицателей. Он был основан рыцарем-провидцем Джалендрелом и вернулся на Землю лишь со Вторым Возрождением, после долгого заточения в Аркадии. Члены дома от природы получают пророческие видения во снах и медитации, но их предупреждениям часто не верят. На доме лежит позор давней ереси, и чуждые сущности Тёмного двора способны распознать Бомайнов, что делает их мишенью.",
  "wod.house.daireann": "Дом Дайреанн — дом ши кельтских корней, формально связанный с Неблагим двором, но сочетающий черты обоих дворов. В Мифическую эпоху его члены были целителями, воинами и защитниками, а вернулись на Землю, чтобы противостоять фоморам. Превыше всего Дайреанны чтят три закона — честь, месть и гостеприимство. Они бесстрашны в бою, но не умеют хранить тайны и склонны хвастаться своими подвигами.",
  "wod.house.dougal": "Дом Дугал — Благой дом ши, прославленный своими мастерами и кузнецами, создающими лучшее оружие и доспехи в Грёзе. Его члены практичны, трудолюбивы и, в отличие от многих ши, уважительно относятся к простолюдинам-ремесленникам. По преданию, каждый член дома несёт какой-либо телесный изъян, напоминающий об увечье основателя. Дугалы ценят дело больше слов и верность больше блеска.",
  "wod.house.eiluned": "Дом Эйлунд — Благой дом ши, хранителей тайн и знатоков магии. Его члены славятся мастерством чародейства, проницательностью и умением плести интриги, оставаясь в тени. Формально дом верен Благому двору, но другие ши относятся к нему с недоверием из-за его скрытности. Эйлунды ценят знание как высшую форму власти и неохотно делятся своими секретами.",
  "wod.house.fiona": "Дом Фиона — Благой дом ши, известный страстностью, отвагой и романтическими похождениями. Его члены — пылкие воины и искатели приключений, которые бросаются в бой и в любовь с одинаковым жаром. Фионы искренни, великодушны и верны друзьям, а среди простолюдинов пользуются уважением за открытость. Их слабость — безрассудная горячность, из-за которой они легко забывают об осторожности.",
  "wod.house.gwydion": "Дом Гвидион — благородный Благой дом ши, считающийся самым знатным и традиционно поставляющий Верховных королей. Его члены — прирождённые правители, судьи и полководцы, гордые и требовательные к себе и другим. Гвидионы ставят во главу угла справедливость и честь. Их слабость — подозрительность и гнев: им трудно доверять другим, а оскорбление вызывает у них яростную вспышку.",
  "wod.house.leanhaun": "Дом Лианнан — Неблагой дом ши, члены которого выступают музами для смертных художников, поэтов и музыкантов. Они разжигают в своих подопечных творческий огонь, но при этом питаются их Гламуром, нередко истощая вдохновлённых людей. Лианнаны изящны, меланхоличны и окружены аурой трагической красоты. Без постоянного источника Гламура они быстро увядают, поэтому их жизнь — вечный поиск новых талантов.",
  "wod.house.liam": "Дом Лиам — изгнанный дом ши, некогда Благой, отвергнутый остальной знатью за близость к людям. Именно Лиамы, согласно преданию, открыли Путь Подменыша — ритуал, позволяющий фейри рождаться в смертных телах и пережить Раскол. Члены дома сочувствуют простолюдинам и смертным и часто выступают их заступниками. Из-за изгнания многие ши относятся к ним с пренебрежением.",
  "wod.house.scathach": "Дом Скатах — дом ши, не примыкающий ни к Благому, ни к Неблагому двору. Его основательница — легендарная ирландская воительница Скатах, наставница героев. Дом прошёл ритуал Пути Подменыша и отчасти стал смертным, поэтому лучше других пережил Раскол. Скатахи — молчаливые и смертоносные стражи на окраинах общества фейри, защищающие всех фей от древних врагов; за серые одежды их называют «Серыми странниками».",
  "wod.house.varich": "Дом Варич — Неблагой дом ши из России, ведущий род от древних вил. Он покинул мир смертных, когда старая вера была вытеснена, провёл века в вечной зиме Аркадии и лишь недавно вернулся. Трагедия основателя, преданного в любви, сделала дом исследователем узоров судьбы: Варичи видят закономерности в битве, политике и музыке. Они не могут давать клятвы любви и обязаны принимать любой брошенный им вызов.",
  "wod.lore.awakening": "Знание Пробуждения — Знание Дома Кнутов, связанное с их изначальной ролью дарителей и хранителей жизни. Демон способен чувствовать жизненную силу, исцелять раны и болезни, укреплять тело и изгонять недуги. На высших ступенях он может даже вернуть к жизни недавно умершего. Демон, поглощённый Мукой, обращает эти силы во зло, насылая болезни и истощение.",
  "wod.lore.beasts": "Знание Зверей — Знание Дома Пожирателей (Дома Дикой Природы), дающее власть над животными. Демон может понимать зверей и говорить с ними, призывать их на помощь, подчинять своей воле и смотреть их глазами. На высших ступенях он полностью вселяется в животных или направляет целые стаи и рои против врагов.",
  "wod.lore.celestials": "Знание Небожителей — Знание Дома Дьяволов (Глашатаев), связанное с их ролью небесных вестников. Оно позволяет видеть Веру смертных и демонов в виде сияния, посылать другим видения и послания, усиливать или гасить чужие силы. На высших ступенях демон обрушивает на врага поток небесного огня и даже вмешивается в чужие воззвания, меняя их итог.",
  "wod.lore.death": "Знание Смерти — Знание Дома Убийц (Жнецов), связанное с распадом, старением и концом жизни. Демон может чувствовать приближение смерти, ускорять разложение и износ предметов, иссушать растения и старить живых. На высших ступенях одним прикосновением или взглядом он способен оборвать жизнь.",
  "wod.lore.earth": "Знание Земли — Знание Дома Преступников (Искусников), дающее власть над почвой, камнем и металлом. Демон способен ощущать всё, что происходит в земле вокруг, проходить сквозь камень, придавать ему форму и вызывать его движение. На высших ступенях это Знание позволяет сотрясать землю и обрушивать постройки, словно при землетрясении.",
  "wod.lore.firmament": "Знание Небесного Свода — Знание Дома Кнутов, позволяющее видеть и слышать через воздух, как когда-то они наблюдали за всем миром с небес. Демон может издалека ощущать присутствие людей, находить тех, кого знает, подслушивать и подглядывать за удалёнными местами. На высших ступенях он почти всевидящ в пределах обширной области.",
  "wod.lore.flame": "Знание Пламени — Знание Дома Дьяволов, дающее власть над огнём и жаром. Демон может чувствовать и гасить огонь, управлять его силой и направлением, защищаться от пламени и в конце концов создавать его из ничего. На высоких уровнях это Знание превращается в грозное оружие, способное обратить врагов и целые здания в пепел.",
  "wod.lore.flesh": "Знание Плоти — Знание Дома Пожирателей, позволяющее изменять живую плоть. Демон может укреплять собственное тело, отращивать когти и броню, ускорять заживление, а также исцелять или калечить других. На высших ступенях он полностью перекраивает тела, придавая им любую форму.",
  "wod.lore.forge": "Знание Кузнечного дела — Знание Дома Преступников, раскрывающее их талант творцов. Демон может постигать устройство любой вещи, управлять механизмами, усиливать или портить предметы и наделять их особыми свойствами. На высших ступенях он создаёт настоящие артефакты и реликвии, заключая в них часть собственной силы или даже связанного духа.",
  "wod.lore.light": "Знание Света — Знание Дома Извергов (Провидцев), дающее власть над светом и тьмой. Демон может усиливать или гасить освещение, ослеплять врагов, окутываться тенью и создавать иллюзорные образы из света. На высших ступенях он сплетает сложные и убедительные иллюзии и обрушивает на врагов испепеляющие лучи.",
  "wod.lore.longing": "Знание Желания — Знание Дома Осквернителей (Нереид), связанное с чувствами и мечтами. Демон может читать эмоции и сокровенные желания людей, усиливать или гасить чувства, вдохновлять на творчество и внушать тоску по недостижимому. На высоких ступенях он полностью управляет эмоциональным состоянием человека. Поглощённый Мукой демон превращает желания в навязчивые страсти.",
  "wod.lore.paths": "Знание Путей — Знание Дома Преступников, связанное с дорогами, путями и пространством между местами. Демон всегда находит верную дорогу, может скрыть путь от чужих глаз, запутать преследователей или преградить им проход. На высших ступенях он искривляет расстояние, сокращая долгий путь или превращая короткую дорогу в бесконечный лабиринт.",
  "wod.lore.patterns": "Знание Узоров — Знание Дома Извергов, связанное с судьбой, вероятностью и предвидением. Демон может различать нити судьбы, предсказывать ход событий, приносить удачу или неудачу и подталкивать случай в нужную сторону. На высших ступенях он способен переплетать судьбу человека, меняя ход его жизни.",
  "wod.lore.portals": "Знание Порталов — Знание Дома Извергов, дающее власть над вратами, дверями и переходами. Демон может запирать и отпирать любые проходы, чувствовать, куда ведут двери, и защищать их от чужаков. На высших ступенях он открывает порталы между удалёнными местами и мгновенно переносится через огромные расстояния.",
  "wod.lore.radiance": "Знание Сияния — Знание Дома Дьяволов, позволяющее воздействовать на сердца и умы через ангельское величие. Демон может придать голосу непререкаемую власть, вселять в людей надежду и мужество, пробуждать древнюю память о небожителях и внушать преданность. На высших ступенях он оставляет на ауре человека знак благосклонности или немилости и обнажает его истинную природу. Демон, поглощённый Мукой, вместо этого сеет страх и отчаяние.",
  "wod.lore.realms": "Знание Сфер — Знание Дома Убийц, связанное с преградой между миром живых и Царством Теней. Демон может оценивать силу этой преграды, переходить в мир мёртвых и быстро перемещаться по нему, становиться бесплотным. На высших ступенях он дотягивается сквозь завесу, не пересекая её, и открывает временные врата, через которые могут пройти и другие демоны.",
  "wod.lore.spirit": "Знание Душ — Знание Дома Убийц, дающее власть над призраками и душами. Демон может видеть и слышать духов умерших, говорить с ними, призывать их и подчинять своей воле. На высших ступенях он привязывает души к предметам или местам и даже удерживает дух в теле, не позволяя ему уйти.",
  "wod.lore.storms": "Знание Бурь — Знание Дома Осквернителей, дающее власть над водой и погодой. Демон способен управлять водой, дышать под ней, вызывать туман и дождь, а на высших ступенях — призывать настоящие бури с молниями и наводнениями. Это Знание напоминает о том, что Осквернители некогда правили морями и глубинами.",
  "wod.lore.transfiguration": "Знание Метаморфоз — Знание Дома Осквернителей, связанное с изменчивостью облика. Демон может менять собственную внешность, чтобы казаться привлекательнее или выглядеть как другой человек, а также угадывать, каким его хотят видеть окружающие. На высших ступенях он принимает облик любого человека настолько полно, что обман почти невозможно распознать.",
  "wod.lore.wild": "Знание Дикой природы — Знание Дома Пожирателей, дающее власть над растениями и дикой природой. Демон может ускорять или останавливать рост растений, повелевать корнями и лозами, скрываться в лесу и заставлять растительность нападать. На высших ступенях он пробуждает целые чащи и превращает местность в непроходимые дебри.",
  "wod.lore.winds": "Знание Ветра — Знание Дома Кнутов (Ангелов-Хранителей), дающее власть над воздухом и его движением. Демон может вызывать порывы ветра, гасить или усиливать звуки, переносить запахи и голоса и отводить летящие в него предметы. На высших ступенях он поднимает ураганные вихри, способные сметать людей и рушить постройки.",
  "wod.path.accord": "Путь Соглашения Чести — рыцарский кодекс, чьих последователей называют рыцарями. Он основан на верности, данному слову и долгу перед сектой и стаей: нарушить клятву для них хуже смерти. Путь возник ещё в Средние века и сохранился в основном в Шабаше. Его адепты дисциплинированны и надёжны, но требуют того же от других и не прощают предательства.",
  "wod.path.blood": "Путь Крови — религиозное учение Ассамитов, основанное на почитании их прародителя Хакима. Его последователи верят, что дети Каина отмечены проклятием и должны быть либо обращены, либо уничтожены, а сами они стремятся приблизиться к своему основателю, понижая поколение. Путь требует строгой дисциплины, самопожертвования и беспощадности к недостойным. Его адепты — фанатичные и опасные воители веры.",
  "wod.path.caine": "Путь Каина — учение нодистов, изучающих Книгу Нод и другие предания о первом вампире. Они считают, что вампир должен не цепляться за человечность, а стремиться стать подобным Каину, развивая силу своей крови, мудрость и самообладание. Адепты пути — учёные, мистики и проповедники Шабаша, известные аскетизмом и холодной рассудительностью. Многие из них ищут в древних текстах признаки приближения Геенны.",
  "wod.path.cathari": "Путь Катари — учение, восходящее к средневековой ереси альбигойцев. Его последователи верят, что плоть и материальный мир порочны, а вампиры — существа зла, которым предназначено быть искусителями. Поэтому они не подавляют свои желания, а предаются излишествам и вводят во искушение других, чтобы испытать их души. Путь популярен в Шабаше и не требует бессмысленной жестокости — лишь честного принятия своей тёмной природы.",
  "wod.path.feral": "Путь Дикого Сердца — мораль тех, кто принял Зверя как естественную часть себя; его последователей называют зверями. Они живут как хищники: охотятся ради пропитания, а не ради жестокости, избегают лишних раздумий и уважают законы природы. Путь особенно распространён среди Гангрелов. Его адепты прямолинейны, не любят цивилизацию и чувствуют себя дома в диких краях.",
  "wod.path.humanity": "Человечность — мера того, насколько вампир сохранил в себе человека и сдерживает внутреннего Зверя. Её шкала идёт от 10 до 0: каждое жестокое или бесчеловечное деяние грозит потерей пункта, а с падением Человечности вампир становится всё более чуждым смертным и уязвимым для бешенства. При нуле Зверь окончательно поглощает личность. Большинство вампиров, особенно в Камарилье, держатся именно этой морали.",
  "wod.path.lilith": "Путь Лилит — тайное учение бахари, почитающих Лилит, первую жену Адама, как истинную тёмную мать вампиров и наставницу Каина. Они верят, что прозрение достигается через боль и страдание, ведь именно боль учит и преображает. Каина бахари считают неблагодарным учеником, а Книгу Нод — искажённой историей. Последователи пути редки, держатся скрытно и вызывают недоверие у остальных вампиров.",
  "wod.path.metamorph": "Путь Метаморфоз — учение Цимисхов, считающих вампиризм лишь ступенью к чему-то высшему. Его последователи, метаморфисты, стремятся преодолеть и человеческое, и вампирское состояние, изучая свои тела и экспериментируя с плотью с помощью Изменчивости. Ради этой цели они отказываются от эмоций и привязанностей. Метаморфисты замкнуты, холодны и считаются одними из самых чуждых существ в Шабаше.",
  "wod.path.night": "Путь Ночи — мрачное учение, распространённое прежде всего среди Ласомбра; его последователей называют нигилистами. Они считают вампиров проклятыми Богом существами, чья роль в мироздании — быть орудием тьмы и греха, заставляя смертных бояться и каяться. Последователи пути не ищут спасения и не поддаются бессмысленной жестокости: страх, который они сеют, должен быть осмысленным уроком.",
  "wod.path.paradox": "Путь Парадокса — мораль клана Равнос, уходящая корнями в индийские представления о карме и перерождении. Его последователи, шилмуло, верят, что вампиры выпали из колеса сансары, и каждый должен следовать своему предназначению — свадхарме. Одним из её проявлений считается упокоение других вампиров, чтобы вернуть их в круг перерождений. Путь почти исчез вместе с большей частью клана после катастрофической Недели Кошмаров.",
  "wod.path.power": "Путь Власти и Внутреннего Голоса — мораль прирождённых лидеров Шабаша, которых называют объединителями. Они верят, что власть — естественная цель вампира, а слушать нужно лишь собственную волю. Последователь должен заслуженно возвышаться, использовать подчинённых по их способностям и вознаграждать успех, но за неудачи отвечать сам. Этого пути держатся многие епископы и архиепископы секты.",
  "wod.path.scorched": "Путь Выжженного Сердца — суровое учение, распространённое среди Истинных Бруха; его адептов называют непрощающими. Они считают, что любые эмоции порождаются Зверем и ведут к падению, поэтому стремятся полностью их искоренить и руководствоваться лишь логикой. Мораль для них тоже основана на чувствах и потому ненадёжна, а ценность имеют только факты, знание и расчёт. Путь связан с тайной сектой Тал'Махе'Ра.",
  "wod.path.self": "Путь Внутреннего Фокуса — учение, во многом заимствованное из восточных философий; его адептов называют интерналистами. Они считают, что Зверя усмиряет не борьба с миром, а невмешательство и принятие: нужно менять себя, а не обстоятельства. Интерналисты живут настоящим моментом, стремятся к глубокому самопознанию и считают, что отвечают лишь перед самими собой. Путь связан с тайной сектой Тал'Махе'Ра.",
  "wod.path.typhon": "Путь Тифона — религиозная мораль Последователей Сета, чьих адептов называют теофидианами. Они считают, что человеческая душа скована иллюзиями и запретами, а освободить её можно, только разрушив их через порок и соблазн. Главная цель пути — подготовить воскрешение Сета и служить ему. Его последователи терпеливы, расчётливы и в совершенстве знают слабости окружающих.",
  "wod.rage": "Ярость — первобытный гнев гару, неистовая сила Геи, текущая в их жилах. Её значение обычно лежит от 1 до 10: чем оно выше, тем сильнее и опаснее оборотень. Ярость позволяет действовать с нечеловеческой скоростью, но грозит бешенством, в котором гару теряет контроль над собой. Кроме того, высокая Ярость пугает людей и животных, отдаляя оборотня от простых смертных. Изначальный уровень Ярости зависит от ауспиции.",
  "wod.rank.adren": "Адрен — третий, средний ранг гару. Его носители — опытные оборотни, известные в своём септе и за его пределами, которые нередко возглавляют стаи и наставляют молодёжь. Достичь ранга Адрен удаётся немногим, ведь для этого нужна слава, накопленная за годы опасной жизни. Мнение Адренов уже учитывают на советах.",
  "wod.rank.athro": "Атро — четвёртый ранг гару, который получают прославленные герои и мудрецы. Атро нередко занимают важные должности в септе, руководят обрядами или командуют защитой каэрна. Их имена известны во многих септах, а слово имеет большой вес. Это ступень, ведущая к высшему рангу старейшины.",
  "wod.rank.cliath": "Клиат — первый ранг гару, который получает молодой оборотень после Обряда Перехода. Клиат уже признан полноправным членом племени, но ещё должен заслужить славу, честь и мудрость, чтобы подняться выше. От них ждут послушания старшим и готовности учиться, а сами они часто горят желанием проявить себя.",
  "wod.rank.elder": "Старейшина — пятый, высший обычный ранг гару. Его удостаиваются лишь живые легенды, чьи деяния воспевают Галлиарды по всей Нации. Старейшины возглавляют септы и племена, хранят древнюю мудрость и решают судьбы оборотней. Немногие гару доживают до этого ранга, и к их слову прислушиваются даже соперники.",
  "wod.rank.fostern": "Фостерн — второй ранг гару, означающий, что оборотень проявил себя и заслужил признание септа. Фостерны уже имеют опыт сражений и обрядов, им доверяют важные задания и часто — руководство небольшими делами стаи. Это ранг тех, кто перестал быть новичком, но ещё не стал признанным лидером.",
  "wod.sect.cam": "Камарилья — крупнейшая секта вампиров, возникшая в XV веке ради защиты от инквизиции и бунта анархов. Её главный закон — Маскарад: смертные не должны узнать о существовании вампиров. Городами правят Князья, опираясь на Традиции и советы старейшин, а во главе секты стоит Внутренний Круг. Камарилья считает себя открытой для всех вампиров, но её основу составляют кланы Вентру, Тореадор, Тремеры, Бруха, Малкавианы и Носферату.",
  "wod.sect.sab": "Шабаш — воинственная секта вампиров, отвергающая человечность и власть древних Допотопных. Его члены считают себя хищниками, а не людьми, и готовятся к Геенне — последней войне против прародителей. Вампиры Шабаша объединены в стаи, скреплённые ритуалом Вадерии, который заменяет личные кровные узы общей верностью. Ведущие кланы — Ласомбра и Цимисхи, а также антитрибу отступников других кланов. Многие его члены следуют Путям Просветления.",
  "wod.seem.grump": "Старец — облик подменыша, чьё смертное тело достигло зрелого возраста. Старцы накопили знания, опыт и мудрость и часто служат наставниками и советниками. Однако с годами их сильнее давит Банальность, и сохранять связь с Грёзой им всё труднее. За ворчливостью многих старцев скрывается глубокая забота о младших и тревога о будущем фейри.",
  "wod.seem.wilder": "Юноша — облик молодого взрослого подменыша, в котором фейская душа ещё горит ярко. Юноши полны энергии, страсти и бунтарства, стремятся всё испытать и проверить себя. Они уже свободны, как взрослые, но не потеряли связи с Грёзой. Именно юноши чаще всего пускаются в приключения, хотя их порывистость нередко приводит к беде.",
  "wod.vamp.assamite": "Ассамиты — независимый клан из крепости Аламут на Ближнем Востоке, почитающий своего прародителя Хакима. Миру они известны как непревзойдённые убийцы, берущие плату кровью вампиров, хотя в клане есть также касты учёных-визирей и колдунов. Их Дисциплины — Стремительность, Затемнение и Квиетус, искусство смертоносной крови. Долгое время их сдерживало проклятие Тремеров, мешавшее пить кровь других вампиров.",
  "wod.vamp.brujah": "Бруха — клан бунтарей и вечных идеалистов. Когда-то это были философы-воины древнего Карфагена, а ныне многие из них — уличные смутьяны, анархи и революционеры. Их кровь дарует Стремительность, Мощь и Присутствие, но вместе с ней — вспыльчивый нрав: Бруха легче других впадают в бешенство. Клан входит в Камарилью, хотя мирится с ней неохотно и постоянно спорит со старейшинами.",
  "wod.vamp.gangrel": "Гангрел — клан одиночек и странников, ближе всех стоящих к Зверю. Они бродят по диким землям, ночуют прямо в почве и слывут лучшими бойцами среди вампиров. Их Дисциплины — Анимализм, Стойкость и Превращение, позволяющее отращивать когти и принимать облик волка или летучей мыши. Каждое бешенство оставляет на теле Гангрела звериную черту. На рубеже тысячелетия большая часть клана покинула Камарилью и стала независимой.",
  "wod.vamp.giovanni": "Джованни — независимый клан некромантов, одновременно являющийся богатой венецианской семьёй банкиров и торговцев. Они пришли к власти, уничтожив в XV веке клан Каппадокийцев и его основателя. Их Дисциплины — Некромантия, Доминирование и Мощь; укус Джованни причиняет жертве мучительную боль. Клан держится особняком, заключив с Камарильей «Обещание» не вмешиваться в её дела, и ставит семью превыше всего.",
  "wod.vamp.lasombra": "Ласомбра — гордый клан аристократов и манипуляторов, повелевающих тьмой. Их уникальная Дисциплина Тенебрация позволяет вызывать живые тени и щупальца мрака; кроме неё, они владеют Доминированием и Мощью. Ласомбра не отражаются в зеркалах. Клан исторически связан с Церковью, и почти весь он служит Шабашу, где его члены занимают многие руководящие посты.",
  "wod.vamp.malkavian": "Малкавианы — клан безумцев и провидцев. Каждый из них страдает неизлечимым психическим расстройством, но в этом безумии часто скрывается пугающая проницательность. Дисциплины клана — Прорицание, Помешательство и Затемнение; их кровь также связывает их в загадочную общую «Паутину». Малкавианов боятся и недооценивают одновременно: их шутки и пророчества нередко оказываются правдой. Клан входит в Камарилью.",
  "wod.vamp.nosferatu": "Носферату — клан, чьё Становление превращает человека в чудовищно уродливое существо. Не в силах показаться среди смертных, они прячутся в канализациях и подземельях, создавая там целые тайные владения. Нужда научила их собирать слухи и секреты, и сегодня Носферату — лучшие торговцы информацией в мире вампиров. Их Дисциплины — Анимализм, Затемнение и Мощь. Клан известен сплочённостью и входит в Камарилью.",
  "wod.vamp.setite": "Последователи Сета — независимый клан, ведущий род от египетского бога тьмы Сета и почитающий его как божество. Сетиты — искусители и торговцы пороками: они находят слабости людей и вампиров и опутывают их зависимостями, считая это путём к освобождению души. Их Дисциплины — Затемнение, Присутствие и Змеиность. Яркий свет особенно губителен для них. Почти все остальные вампиры относятся к Сетитам с подозрением.",
  "wod.vamp.toreador": "Тореадор — клан художников, ценителей и светских львов. Они окружают себя красотой, покровительствуют искусствам и задают тон в обществе вампиров, за что другие кланы порой считают их пустыми декадентами. Их Дисциплины — Прорицание, Стремительность и Присутствие. Слабость клана — способность замирать в оцепенении перед чем-то по-настоящему прекрасным. Тореадор — один из столпов Камарильи и ревностные хранители Маскарада.",
  "wod.vamp.tremere": "Тремеры — клан колдунов крови, произошедший от средневековых магов, которые обрели бессмертие ритуалами и кражей вампирской крови. Их главная Дисциплина — Тауматургия, магия крови; также им доступны Прорицание и Доминирование. Клан устроен как строгая пирамида с центром в Вене, а каждый неонат частично связан узами крови со старейшинами клана. Из-за своего происхождения Тремеры вызывают недоверие, но остаются ценной и влиятельной частью Камарильи.",
  "wod.vamp.tzimisce": "Цимисхи — древний клан учёных и владык Восточной Европы, прежде всего Карпат. Их коронная Дисциплина Изменчивость позволяет лепить плоть и кости, как глину, — своих и чужих; также им доступны Анимализм и Прорицание. Цимисхи должны спать в земле своей родины, иначе теряют силы. Они славятся гостеприимством, педантичностью и холодной бесчеловечностью и вместе с Ласомбра составляют ядро Шабаша.",
  "wod.vamp.ventrue": "Вентру — клан аристократов, правителей и дельцов, считающий себя опорой Камарильи. Из их рядов чаще всего выходят Князья, а сами они ценят традиции, порядок и личную ответственность за свои владения. Их Дисциплины — Доминирование, Стойкость и Присутствие. Проклятие клана — привередливость в питании: каждый Вентру может пить кровь лишь людей определённого рода, иначе его организм её отвергает.",
  "wod.wolf.fangs": "Серебряные Клыки — древнейшее королевское племя гару, издавна правящее Нацией. Их покровитель — Сокол, а родословные тщательно оберегаются ради чистоты крови. Но века близкородственных браков принесли свои плоды: многие Клыки страдают безумием и странностями. Они благородны, горды и отважны, однако их право на власть всё чаще ставят под сомнение.",
  "wod.wolf.fenris": "Потомство Фенрира — племя воинов с корнями в германских и скандинавских землях. Они ценят силу, храбрость и славу в бою, а слабость презирают; путь Потомства — битва с Вирмом без отступления. Их покровитель — великий волк Фенрир. Это одни из самых грозных бойцов Нации, но их жёсткость, нетерпимость и тёмные страницы истории вызывают споры даже среди союзников.",
  "wod.wolf.fianna": "Фианна — племя бардов, воинов и сказителей из кельтских земель Ирландии, Шотландии и Уэльса. Они хранят песни и легенды гару, любят пиры, музыку и поэзию, а их ярость так же сильна, как их радость. Их покровитель — Олень, а с народом фей племя связывает давняя дружба. Фианна страстны, верны друзьям и известны как лучшие Галлиарды Нации.",
  "wod.wolf.gaia": "Дети Геи — племя миротворцев и целителей среди гару. Они стараются примирить враждующие племена, ищут союзников среди людей и верят, что Апокалипсис можно встретить не только когтями, но и состраданием. Их покровитель — Единорог. Многие считают их слишком мягкими, но Дети Геи способны яростно сражаться, защищая слабых. Племя открыто для всех, кто разделяет их идеалы.",
  "wod.wolf.glass": "Ходящие по Стеклу — самое городское племя гару, принявшее технологии и современный мир. Они живут в мегаполисах, разбираются в компьютерах, финансах и криминальном мире и общаются с духами машин и электричества. Их покровитель — Таракан, дух городов и сетей. Многие гару подозревают их в сближении с Вивером, но Ходящие по Стеклу уверены, что город тоже нужно защищать.",
  "wod.wolf.gnawers": "Грызущие Кости — племя бездомных и отверженных, живущих на самом дне городов. Они защищают бедняков, бродяг и всех, кого общество бросило, и прекрасно знают трущобы, свалки и подворотни. Их покровитель — Крыса. Другие племена долго смотрели на них свысока, но Грызущие Кости гордятся своей стойкостью, находчивостью и умением выживать где угодно.",
  "wod.wolf.shadow": "Теневые Владыки — честолюбивое племя политиков и интриганов родом из Восточной Европы. Они уважают силу, считают, что лидером должен быть самый способный, и открыто метят на место Серебряных Клыков. Их покровитель — Дед Гром, дух бури. Другие племена не доверяют их методам, но признают, что Владыки действуют результативно и беспощадно против врагов Геи.",
  "wod.wolf.stargazers": "Звездочёты — племя философов и мистиков, ищущих внутреннего равновесия через медитацию, боевые искусства и созерцание звёзд. Они стремятся обуздать свою Ярость и понять ход судьбы, а их учения во многом близки восточным традициям. Их покровитель — Химера, дух загадок и перемен. Из-за разногласий с другими племенами Звездочёты одно время покидали Нацию гару и сблизились с оборотнями Азии.",
  "wod.wolf.striders": "Безмолвные Странники — племя скитальцев, вестников и разведчиков, происходящее из Древнего Египта. Давнее проклятие изгнало их с родины, и с тех пор они не находят покоя, бродя по миру и разнося вести между септами. Их покровитель — Сова. Странники тесно связаны с миром мёртвых и духами предков, и другие гару считают их загадочными и немного жутковатыми.",
  "wod.wolf.talons": "Красные Когти — племя, принимающее в свои ряды только волков по рождению. Они винят людей в уничтожении дикой природы и считают, что лучший путь спасения Геи — резко сократить человечество. Их покровитель — Грифон. Когти свирепы, плохо понимают человеческий мир и сторонятся его, а с другими племенами ладят с трудом.",
  "wod.wolf.uktena": "Уктена — племя мистиков и хранителей тайн, родом из коренных народов Северной Америки. Они изучают тёмные знания, охраняют места, где заточены древние злые духи, и порой рискуют, используя сам Вирм против его же созданий. Их покровитель — Уктена, великий рогатый змей вод. Другие племена уважают их мудрость, но опасаются их увлечения запретным.",
  "wod.wolf.wendigo": "Вендиго — суровое племя воинов из коренных народов северных лесов Америки. Они хранят традиции предков, сражаются с Вирмом и с наследием колонизаторов и не доверяют пришедшим из Европы племенам. Их покровитель — Вендиго, дух голода и холодного ветра. Это стойкие охотники, сильные в зимних краях и упорные в верности своему народу.",
  "wr.mut": "Мутации в мирах Warhammer считаются «дарами» богов Хаоса — знаками их внимания к смертному. Поначалу это может быть рог, лишний глаз или чешуя, а дальше — щупальца, клешни и всё более чудовищные изменения. Для одних это благословение и путь к могуществу, для других — проклятие. Тот, кто получает слишком много даров, рискует лишиться разума и облика и превратиться в отродье Хаоса — бесформенную, вечно меняющуюся тварь. На десятой мутации это и происходит.",
  "wr.of.khorne": "Кхорн — Кровавый Бог, бог Хаоса, олицетворяющий ярость, войну и убийство. Он восседает на троне из черепов посреди моря крови и требует от последователей лишь одного: проливать кровь, неважно чью. Кхорн презирает колдовство и уважает только воинскую доблесть и честный бой. Его служители — берсерки и одержимые бойцы, а его знак и число — восемь. Самая прямолинейная и самая страшная на поле боя из сил Хаоса.",
  "wr.of.nurgle": "Нургл — Дедушка Нургл, бог Хаоса, связанный с болезнями, разложением, а также с отчаянием и упорством перед лицом смерти. Парадоксально, но он добродушен: он щедро одаривает смертных своими «дарами» — чумой и гниением — и искренне любит своих последователей. Его служители раздуты и покрыты язвами, но не чувствуют боли и почти неуязвимы. Нургл обещает избавление от страха смерти через принятие вечного круговорота распада и возрождения. Его число — семь.",
  "wr.of.rat": "Рогатая Крыса — божество скавенов из Warhammer Fantasy, которое многие считают отдельной силой Хаоса, стоящей рядом с четырьмя великими богами. Это бог предательства, хитрости, голода и плодовитости, обещающий крысолюдям власть над миром. Скавены верят, что однажды Рогатая Крыса займёт место Великого Рогатого и поглотит всё сущее. Её волю толкует Совет Тринадцати и пророки-серые провидцы. Её число — тринадцать.",
  "wr.of.slaanesh": "Слаанеш — Принц Наслаждений, самый молодой из великих богов Хаоса, воплощение излишеств, гордыни, тщеславия и стремления к совершенству. Его рождение в мире эльдаров стало катастрофой, погубившей их империю, и с тех пор он жаждет заполучить их души. Последователи Слаанеша ищут всё более сильных ощущений, пока не теряют всякую меру. Он соблазняет обещанием идеала и исполнения желаний, но служение ему ведёт к пресыщению и падению. Его число — шесть.",
  "wr.of.tzeentch": "Тзинч — Изменяющий Пути, бог Хаоса перемен, надежды, честолюбия, магии и интриг. Он плетёт бесконечные заговоры, столь запутанные, что их истинную цель не знает никто, кроме него самого, а порой и он. Его последователи — колдуны, мятежники и все, кто жаждет знаний и власти. Дары Тзинча непредсказуемы: тело избранника может постоянно меняться. Он — вечный соперник Нургла, ведь перемена противоположна застою. Его число — девять."
});
